fn should_log_agent_key(key: KeyEvent) -> bool {
    key.modifiers.intersects(
        KeyModifiers::CONTROL
            | KeyModifiers::ALT
            | KeyModifiers::SHIFT
            | KeyModifiers::SUPER
            | KeyModifiers::HYPER
            | KeyModifiers::META,
    ) || matches!(
        key.code,
        KeyCode::Left
            | KeyCode::Right
            | KeyCode::Up
            | KeyCode::Down
            | KeyCode::Home
            | KeyCode::End
            | KeyCode::PageUp
            | KeyCode::PageDown
            | KeyCode::F(_)
    )
}

fn debug_log_agent_key(key: KeyEvent, action: &str) {
    // Gate before building the JSON value: `debug_log` arguments are
    // evaluated eagerly, and this runs per keystroke.
    if !DEBUG_ENABLED.load(Ordering::Relaxed) {
        return;
    }
    debug_log(
        "agent_key",
        serde_json::json!({
            "action": action,
            "code": key_code_label(key),
            "modifiers": format!("{:?}", key.modifiers),
            "kind": format!("{:?}", key.kind),
            "state": format!("{:?}", key.state),
        }),
    );
}

