fn input_mode_label(mode: &InputMode) -> &'static str {
    match mode {
        InputMode::Normal => "normal",
        InputMode::SearchChoice { .. } => "search_choice",
        InputMode::Filter { .. } => "filter",
        InputMode::AiSearch { .. } => "ai_search",
        InputMode::DeleteConfirm { .. } => "delete_confirm",
        InputMode::CreateFolderConfirm { .. } => "create_folder_confirm",
        InputMode::RestoreDataConfirm { .. } => "restore_data_confirm",
        InputMode::AgentLaunch { .. } => "agent_launch",
        InputMode::CloneOptions { .. } => "clone_options",
        InputMode::NewSession { .. } => "new_session",
        InputMode::TitleEdit { .. } => "title_edit",
        InputMode::Settings { .. } => "settings",
        InputMode::Notice { .. } => "notice",
    }
}

fn key_code_label(key: KeyEvent) -> String {
    match key.code {
        KeyCode::Backspace => "backspace".to_string(),
        KeyCode::Enter => "enter".to_string(),
        KeyCode::Left => "left".to_string(),
        KeyCode::Right => "right".to_string(),
        KeyCode::Up => "up".to_string(),
        KeyCode::Down => "down".to_string(),
        KeyCode::Home => "home".to_string(),
        KeyCode::End => "end".to_string(),
        KeyCode::PageUp => "page_up".to_string(),
        KeyCode::PageDown => "page_down".to_string(),
        KeyCode::Tab => "tab".to_string(),
        KeyCode::BackTab => "back_tab".to_string(),
        KeyCode::Delete => "delete".to_string(),
        KeyCode::Insert => "insert".to_string(),
        KeyCode::F(n) => format!("f{}", n),
        KeyCode::Char(c) if key.modifiers.contains(KeyModifiers::CONTROL) => {
            format!("control_char_u+{:04x}", c as u32)
        }
        KeyCode::Char(_) => "char".to_string(),
        KeyCode::Null => "null".to_string(),
        KeyCode::Esc => "esc".to_string(),
        KeyCode::CapsLock => "caps_lock".to_string(),
        KeyCode::ScrollLock => "scroll_lock".to_string(),
        KeyCode::NumLock => "num_lock".to_string(),
        KeyCode::PrintScreen => "print_screen".to_string(),
        KeyCode::Pause => "pause".to_string(),
        KeyCode::Menu => "menu".to_string(),
        KeyCode::KeypadBegin => "keypad_begin".to_string(),
        KeyCode::Media(media) => format!("media_{:?}", media),
        KeyCode::Modifier(modifier) => format!("modifier_{:?}", modifier),
    }
}

fn debug_key_event_value(key: KeyEvent) -> serde_json::Value {
    serde_json::json!({
        "code": key_code_label(key),
        "modifiers": format!("{:?}", key.modifiers),
        "kind": format!("{:?}", key.kind),
        "state": format!("{:?}", key.state),
    })
}

fn key_event_to_bytes(key: KeyEvent) -> Option<Vec<u8>> {
    let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
    let alt = key.modifiers.contains(KeyModifiers::ALT);
    let mut bytes = Vec::new();

    match key.code {
        KeyCode::Char(c) if ctrl => {
            if alt {
                bytes.push(0x1b);
            }
            let lower = c.to_ascii_lowercase();
            let code = match lower {
                'a'..='z' => (lower as u8) - b'a' + 1,
                '[' => 0x1b,
                '\\' => 0x1c,
                ']' => 0x1d,
                '^' => 0x1e,
                '_' => 0x1f,
                '?' => 0x7f,
                _ => return None,
            };
            bytes.push(code);
        }
        KeyCode::Char(c) => {
            if alt {
                bytes.push(0x1b);
            }
            let mut buf = [0; 4];
            bytes.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
        }
        KeyCode::Enter => {
            if alt {
                bytes.push(0x1b);
            }
            bytes.push(b'\r');
        }
        KeyCode::Tab => {
            if alt {
                bytes.push(0x1b);
            }
            bytes.push(b'\t');
        }
        KeyCode::Backspace => {
            if alt {
                bytes.push(0x1b);
            }
            bytes.push(0x7f);
        }
        KeyCode::Esc => {
            if alt {
                bytes.push(0x1b);
            }
            bytes.push(0x1b);
        }
        KeyCode::Up => bytes.extend_from_slice(&modified_csi_final(b'A', key.modifiers)),
        KeyCode::Down => bytes.extend_from_slice(&modified_csi_final(b'B', key.modifiers)),
        KeyCode::Right => bytes.extend_from_slice(&modified_csi_final(b'C', key.modifiers)),
        KeyCode::Left => bytes.extend_from_slice(&modified_csi_final(b'D', key.modifiers)),
        KeyCode::Home => bytes.extend_from_slice(&modified_csi_final(b'H', key.modifiers)),
        KeyCode::End => bytes.extend_from_slice(&modified_csi_final(b'F', key.modifiers)),
        KeyCode::PageUp => bytes.extend_from_slice(&modified_csi_tilde(5, key.modifiers)),
        KeyCode::PageDown => bytes.extend_from_slice(&modified_csi_tilde(6, key.modifiers)),
        KeyCode::Delete => bytes.extend_from_slice(&modified_csi_tilde(3, key.modifiers)),
        KeyCode::Insert => bytes.extend_from_slice(&modified_csi_tilde(2, key.modifiers)),
        KeyCode::F(n) => {
            if alt {
                bytes.push(0x1b);
            }
            match n {
                1 => bytes.extend_from_slice(b"\x1bOP"),
                2 => bytes.extend_from_slice(b"\x1bOQ"),
                3 => bytes.extend_from_slice(b"\x1bOR"),
                4 => bytes.extend_from_slice(b"\x1bOS"),
                5 => bytes.extend_from_slice(b"\x1b[15~"),
                6 => bytes.extend_from_slice(b"\x1b[17~"),
                7 => bytes.extend_from_slice(b"\x1b[18~"),
                8 => bytes.extend_from_slice(b"\x1b[19~"),
                9 => bytes.extend_from_slice(b"\x1b[20~"),
                10 => bytes.extend_from_slice(b"\x1b[21~"),
                11 => bytes.extend_from_slice(b"\x1b[23~"),
                12 => bytes.extend_from_slice(b"\x1b[24~"),
                _ => return None,
            }
        }
        _ => return None,
    }

    Some(bytes)
}

fn modified_csi_final(final_byte: u8, modifiers: KeyModifiers) -> Vec<u8> {
    if let Some(modifier_param) = xterm_modifier_param(modifiers) {
        format!("\x1b[1;{}{}", modifier_param, final_byte as char).into_bytes()
    } else {
        format!("\x1b[{}", final_byte as char).into_bytes()
    }
}

fn modified_csi_tilde(code: u8, modifiers: KeyModifiers) -> Vec<u8> {
    if let Some(modifier_param) = xterm_modifier_param(modifiers) {
        format!("\x1b[{};{}~", code, modifier_param).into_bytes()
    } else {
        format!("\x1b[{}~", code).into_bytes()
    }
}

fn xterm_modifier_param(modifiers: KeyModifiers) -> Option<u8> {
    let mut param = 1;
    if modifiers.contains(KeyModifiers::SHIFT) {
        param += 1;
    }
    if modifiers.contains(KeyModifiers::ALT) {
        param += 2;
    }
    if modifiers.contains(KeyModifiers::CONTROL) {
        param += 4;
    }
    (param > 1).then_some(param)
}

fn paste_text_to_agent_bytes(text: &str, bracketed_paste_mode: bool) -> Vec<u8> {
    if bracketed_paste_mode {
        let mut bytes = Vec::with_capacity(
            BRACKETED_PASTE_INPUT_START.len() + text.len() + BRACKETED_PASTE_INPUT_END.len(),
        );
        bytes.extend_from_slice(BRACKETED_PASTE_INPUT_START);
        bytes.extend_from_slice(text.as_bytes());
        bytes.extend_from_slice(BRACKETED_PASTE_INPUT_END);
        return bytes;
    }

    let mut bytes = Vec::with_capacity(text.len());
    let raw = text.as_bytes();
    let mut index = 0usize;
    while index < raw.len() {
        match raw[index] {
            b'\r' => {
                bytes.push(b'\r');
                index += 1;
                if raw.get(index) == Some(&b'\n') {
                    index += 1;
                }
            }
            b'\n' => {
                bytes.push(b'\r');
                index += 1;
            }
            byte => {
                bytes.push(byte);
                index += 1;
            }
        }
    }
    bytes
}

fn text_field_paste_text(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut chars = text.chars().peekable();
    while let Some(ch) = chars.next() {
        match ch {
            '\r' => {
                if chars.peek() == Some(&'\n') {
                    chars.next();
                }
                out.push(' ');
            }
            '\n' | '\t' => out.push(' '),
            _ if ch.is_control() => {}
            _ => out.push(ch),
        }
    }
    out
}

fn insert_str_at_cursor(draft: &mut String, cursor: &mut usize, text: &str) {
    if text.is_empty() {
        return;
    }
    *cursor = clamp_to_char_boundary(draft, *cursor);
    draft.insert_str(*cursor, text);
    *cursor += text.len();
}

fn update_bracketed_paste_mode_from_output(
    enabled: &mut bool,
    scan_tail: &mut Vec<u8>,
    data: &[u8],
) -> bool {
    if data.is_empty() {
        return false;
    }
    let before = *enabled;
    let previous_len = scan_tail.len();
    let mut scan = Vec::with_capacity(scan_tail.len() + data.len());
    scan.extend_from_slice(scan_tail);
    scan.extend_from_slice(data);

    let mut index = 0usize;
    while index < scan.len() {
        let Some(start_offset) = scan[index..]
            .windows(3)
            .position(|window| window == b"\x1b[?")
        else {
            break;
        };
        let start = index + start_offset;
        let params_start = start + 3;
        let Some(final_offset) = scan[params_start..]
            .iter()
            .position(|byte| (0x40..=0x7e).contains(byte))
        else {
            break;
        };
        let final_index = params_start + final_offset;
        if final_index + 1 > previous_len {
            let final_byte = scan[final_index];
            if matches!(final_byte, b'h' | b'l')
                && private_mode_params_include_bracketed_paste(&scan[params_start..final_index])
            {
                *enabled = final_byte == b'h';
            }
        }
        index = final_index + 1;
    }

    let keep_start = scan
        .len()
        .saturating_sub(BRACKETED_PASTE_MODE_SCAN_TAIL_BYTES);
    *scan_tail = scan[keep_start..].to_vec();
    before != *enabled
}

fn private_mode_params_include_bracketed_paste(params: &[u8]) -> bool {
    let mut value = 0u32;
    let mut in_digits = false;
    for &byte in params {
        if byte.is_ascii_digit() {
            value = value
                .saturating_mul(10)
                .saturating_add(u32::from(byte - b'0'));
            in_digits = true;
            continue;
        }
        if in_digits && value == BRACKETED_PASTE_MODE_PARAM {
            return true;
        }
        value = 0;
        in_digits = false;
    }
    in_digits && value == BRACKETED_PASTE_MODE_PARAM
}

