fn startup_spinner_frame(elapsed: Duration) -> &'static str {
    let index =
        ((elapsed.as_millis() / STARTUP_SPINNER_TICK_MS) as usize) % STARTUP_SPINNER_FRAMES.len();
    STARTUP_SPINNER_FRAMES[index]
}

fn copy_stats_summary(stats: &session::data::CopyStats) -> String {
    format!(
        "{} files, {} dirs, {} symlinks, {} bytes",
        stats.files, stats.dirs, stats.symlinks, stats.bytes
    )
}

fn progress_percent(processed: usize, total: usize) -> Option<u8> {
    if total == 0 {
        return None;
    }
    let percent = processed.saturating_mul(100).saturating_add(total / 2) / total;
    Some(percent.min(100) as u8)
}

fn ai_search_progress_percent(indexed: usize, total: usize) -> Option<u8> {
    progress_percent(indexed, total)
}

fn search_progress_summary(pending: &SearchPending) -> String {
    if pending.total == 0 {
        return "preparing session list".to_string();
    }
    let percent = progress_percent(pending.processed, pending.total).unwrap_or(0);
    format!(
        "{}/{} sessions  {}%  hits {}  errors {}",
        pending.processed.min(pending.total),
        pending.total,
        percent,
        pending.hits,
        pending.load_errors,
    )
}

fn ai_search_progress_summary(pending: &AiSearchPending) -> Option<String> {
    if pending.total == 0 {
        return Some("0 sessions indexed".to_string());
    }
    let percent = ai_search_progress_percent(pending.indexed, pending.total).unwrap_or(0);
    Some(format!(
        "{}/{} previews  {}%  reused {}  written {}",
        pending.indexed.min(pending.total),
        pending.total,
        percent,
        pending.reused,
        pending.written
    ))
}

fn copy_percent_summary(
    stats: Option<&session::data::CopyStats>,
    total: Option<&session::data::CopyStats>,
) -> Option<String> {
    let stats = stats?;
    let total = total?;
    let (done, total) = if total.bytes > 0 {
        (stats.bytes, total.bytes)
    } else if total.files > 0 {
        (stats.files, total.files)
    } else if total.symlinks > 0 {
        (stats.symlinks, total.symlinks)
    } else if total.dirs > 0 {
        (stats.dirs, total.dirs)
    } else {
        return Some("100%".to_string());
    };
    let percent = done
        .saturating_mul(100)
        .checked_div(total)
        .unwrap_or(0)
        .min(100);
    Some(format!("{percent}%"))
}

fn render_agent_startup_spinner(
    buf: &mut Buffer,
    area: Rect,
    info: &SessionInfo,
    started_at: Instant,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }

    let label = format!(
        "{} starting {} agent {}",
        startup_spinner_frame(started_at.elapsed()),
        info.provider.as_str(),
        truncate_width(&info.session_id, 18)
    );
    let label = truncate_width(&label, area.width as usize);
    let label_width = UnicodeWidthStr::width(label.as_str()).min(area.width as usize) as u16;
    let x = area
        .x
        .saturating_add(area.width.saturating_sub(label_width) / 2);
    let y = area.y.saturating_add(area.height / 2);
    let available = area.right().saturating_sub(x).min(area.width).max(1) as usize;
    buf.set_stringn(
        x,
        y,
        label,
        available,
        Style::default()
            .fg(THEME_SHORTCUT)
            .bg(AGENT_DEFAULT_BG)
            .add_modifier(Modifier::BOLD),
    );
}

#[derive(Clone)]
struct AgentRenderOutcome {
    cursor: Option<(u16, u16)>,
    scrollback_offset: usize,
    command_line: String,
    info: SessionInfo,
}

fn render_agent_client_pane(
    f: &mut ratatui::Frame,
    agent: &mut AgentClient,
    area: Rect,
    frame_title: Option<&str>,
    focused: bool,
) -> AgentRenderOutcome {
    let content_area = if let Some(title) = frame_title {
        fill_area(f.buffer_mut(), area, Style::default().bg(AGENT_DEFAULT_BG));
        let border_color = if focused {
            THEME_BORDER_ACTIVE
        } else {
            THEME_BORDER
        };
        let block = Block::default()
            .borders(Borders::ALL)
            .border_style(Style::default().fg(border_color).bg(AGENT_DEFAULT_BG))
            .style(Style::default().bg(AGENT_DEFAULT_BG))
            .title(title.to_string());
        f.render_widget(block, area);
        pane_inner(area)
    } else {
        area
    };

    let (agent_screen_rows, agent_screen_cols) = agent_screen_size_for_area(content_area);
    agent.resize(agent_screen_cols, agent_screen_rows);
    // Output is already in the parser — the reader thread pushed it via
    // process_agent_event before this draw was scheduled. No socket read
    // happens on the render path.
    let screen_size = agent.parser.screen().size();
    if screen_size != (agent_screen_rows, agent_screen_cols) {
        debug_log(
            "agent_parser_size_corrected",
            serde_json::json!({
                "provider": agent.info.provider.as_str(),
                "session_id": &agent.info.session_id,
                "screen_rows": screen_size.0,
                "screen_cols": screen_size.1,
                "area_rows": content_area.height,
                "area_cols": content_area.width,
                "target_rows": agent_screen_rows,
                "target_cols": agent_screen_cols,
            }),
        );
        agent
            .parser
            .screen_mut()
            .set_size(agent_screen_rows, agent_screen_cols);
    }

    let (cursor, scrollback_offset, render_source) = {
        let startup_spinner_started_at = agent.startup_spinner_started_at();
        let screen = agent.parser.screen();
        let history_scroll_offset = agent.history_scroll_offset;
        let parser_scrollback = screen.scrollback();
        let render_source = if parser_scrollback == 0 && history_scroll_offset > 0 {
            "history"
        } else {
            "parser"
        };
        let scrollback_offset = if parser_scrollback > 0 {
            parser_scrollback
        } else {
            history_scroll_offset
        };
        let cursor = if startup_spinner_started_at.is_some()
            || screen.hide_cursor()
            || scrollback_offset > 0
            || !focused
        {
            None
        } else {
            let (row, col) = screen.cursor_position();
            if row < content_area.height && col < content_area.width {
                Some((content_area.x + col, content_area.y + row))
            } else {
                None
            }
        };
        let buf = f.buffer_mut();
        fill_area(buf, content_area, Style::default().bg(AGENT_DEFAULT_BG));
        if render_source == "history" {
            let lines = agent
                .screen_history
                .visible_lines(history_scroll_offset, content_area.height as usize);
            render_plain_agent_history(buf, content_area, &lines);
        } else {
            render_vt100_screen(buf, screen, content_area);
        }
        if let Some(started_at) = startup_spinner_started_at {
            render_agent_startup_spinner(buf, content_area, &agent.info, started_at);
        }
        (cursor, scrollback_offset, render_source)
    };

    if DEBUG_ENABLED.load(Ordering::Relaxed)
        && (scrollback_offset > 0 || TRACE_ENABLED.load(Ordering::Relaxed))
    {
        let visible_rows = content_area.height as usize;
        let max_rows = visible_rows.max(1).min(120);
        let rendered_window = if render_source == "history" {
            debug_history_window_value(
                &agent.screen_history,
                agent.history_scroll_offset,
                visible_rows.max(1),
                max_rows,
            )
        } else {
            let parser_scrollback = agent.parser.screen().scrollback();
            debug_visible_lines_at_scrollback(&mut agent.parser, parser_scrollback, max_rows)
        };
        // `rendered_window` is this event's diagnostic payload; the generic
        // state dump is redundant with it and only captured under trace.
        let state = TRACE_ENABLED
            .load(Ordering::Relaxed)
            .then(|| debug_agent_client_state_value(agent, visible_rows.max(1), max_rows));
        debug_log(
            "agent_render",
            serde_json::json!({
                "provider": agent.info.provider.as_str(),
                "session_id": &agent.info.session_id,
                "area_x": content_area.x,
                "area_y": content_area.y,
                "area_width": content_area.width,
                "area_height": content_area.height,
                "framed": frame_title.is_some(),
                "focused": focused,
                "render_source": render_source,
                "scrollback_offset": scrollback_offset,
                "rendered_window": rendered_window,
                "state": state,
            }),
        );
    }

    AgentRenderOutcome {
        cursor,
        scrollback_offset,
        command_line: agent.command_line.clone(),
        info: agent.info.clone(),
    }
}

fn main_agent_content_area(area: Rect) -> Rect {
    if area.height == 0 {
        return area;
    }
    Rect::new(
        area.x,
        area.y.saturating_add(1),
        area.width,
        area.height.saturating_sub(1),
    )
}

fn main_agent_title(info: &SessionInfo) -> String {
    if is_plain_pty_tool_session_info(info) {
        return live_agent_status_label(info);
    }
    info.title
        .as_deref()
        .filter(|title| !title.trim().is_empty())
        .map(|title| title.to_string())
        .unwrap_or_else(|| live_agent_status_label(info))
}

fn render_main_agent_title_bar(
    f: &mut ratatui::Frame,
    area: Rect,
    info: &SessionInfo,
    focused: bool,
) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    let bar_area = Rect::new(area.x, area.y, area.width, 1);
    let style = if focused {
        Style::default()
            .fg(THEME_FG_STRONG)
            .bg(THEME_SELECTED_BG)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(THEME_FG_DIM).bg(THEME_STATUS_BG)
    };
    fill_area(f.buffer_mut(), bar_area, style);
    let title = truncate_width(
        &main_agent_title(info),
        area.width.saturating_sub(2) as usize,
    );
    f.buffer_mut().set_stringn(
        area.x.saturating_add(1),
        area.y,
        title,
        area.width.saturating_sub(1) as usize,
        style,
    );
}

fn ui_agent(f: &mut ratatui::Frame, app: &mut App) {
    let area = f.area();
    let main_area = Rect::new(
        area.x,
        area.y,
        area.width,
        area.height.saturating_sub(AGENT_STATUS_HEIGHT),
    );
    let status_area = Rect::new(
        area.x,
        area.y + main_area.height,
        area.width,
        AGENT_STATUS_HEIGHT.min(area.height),
    );

    let app_status = app.display_status();
    let active_key = app
        .active_agent
        .as_ref()
        .map(|agent| AgentKey::new(&agent.info));
    let layout = agent_pane_layout_for_area(
        main_area,
        app.agent_sidebar_config_width(),
        app.agent_aux.is_some(),
        app.agent_aux_width,
    );

    if app.active_agent.is_none() {
        f.render_widget(Clear, area);
        return;
    }

    let main_outcome = {
        let agent = app
            .active_agent
            .as_mut()
            .expect("active_agent checked above");
        let main_focused = app.agent_focus == AgentFocusPane::Main;
        render_main_agent_title_bar(f, layout.main, &agent.info, main_focused);
        render_agent_client_pane(
            f,
            agent,
            main_agent_content_area(layout.main),
            None,
            main_focused,
        )
    };

    let auxiliary_outcome =
        if let (Some(aux), Some(aux_area)) = (app.agent_aux.as_mut(), layout.auxiliary) {
            Some(render_agent_client_pane(
                f,
                &mut aux.agent,
                aux_area,
                Some(aux.kind.title()),
                app.agent_focus == AgentFocusPane::Auxiliary,
            ))
        } else {
            None
        };

    let focused_outcome = if app.agent_focus == AgentFocusPane::Auxiliary {
        auxiliary_outcome.as_ref().unwrap_or(&main_outcome)
    } else {
        &main_outcome
    };

    let focused_cursor = match app.agent_focus {
        AgentFocusPane::Main => main_outcome.cursor,
        AgentFocusPane::Auxiliary => auxiliary_outcome
            .as_ref()
            .and_then(|outcome| outcome.cursor),
        AgentFocusPane::Sidebar => None,
    };

    let buf = f.buffer_mut();
    fill_area(buf, status_area, theme_status_style());
    let agent_help_items = agent_help_items(&app.keybindings);
    let agent_status_subject = if is_plain_pty_tool_session_info(&focused_outcome.info) {
        live_agent_status_label(&focused_outcome.info)
    } else {
        format!(
            "{} {}",
            focused_outcome.info.provider.as_str(),
            truncate_width(&focused_outcome.info.session_id, 18)
        )
    };
    let focus_label = match app.agent_focus {
        AgentFocusPane::Sidebar => "focus agents".to_string(),
        AgentFocusPane::Main => "focus agent".to_string(),
        AgentFocusPane::Auxiliary => app
            .agent_aux
            .as_ref()
            .map(|aux| format!("focus right {}", aux.kind.label()))
            .unwrap_or_else(|| "focus right".to_string()),
    };
    let mut status_parts = vec![agent_status_subject, focus_label];
    if let Some(aux) = app.agent_aux.as_ref() {
        status_parts.push(format!("right {}", aux.kind.label()));
    }
    if !app_status.is_empty() {
        status_parts.push(app_status);
    }
    if focused_outcome.scrollback_offset > 0 {
        status_parts.push(format!(
            "scrollback {} up",
            focused_outcome.scrollback_offset
        ));
    }
    let mut status_spans = Vec::new();
    let mut used = 0usize;
    let width = status_area.width as usize;
    let status_style = theme_status_style();
    let status_dim_style = Style::default().fg(THEME_FG_DIM).bg(THEME_STATUS_BG);
    let shortcut_style = Style::default().fg(THEME_SHORTCUT).bg(THEME_STATUS_BG);
    let mut first = true;
    for part in status_parts {
        let separator = if first { " " } else { "  " };
        if !push_help_span(&mut status_spans, separator, status_style, &mut used, width)
            || !push_help_span(&mut status_spans, &part, status_style, &mut used, width)
        {
            break;
        }
        first = false;
    }
    if used < width {
        let _ = push_help_span(&mut status_spans, "  ", status_dim_style, &mut used, width);
        push_help_item_spans(
            &agent_help_items,
            &mut status_spans,
            status_dim_style,
            shortcut_style,
            &mut used,
            width,
        );
    }
    if used < width {
        let _ = push_help_span(&mut status_spans, "  ", status_dim_style, &mut used, width);
        let _ = push_help_span(
            &mut status_spans,
            &focused_outcome.command_line,
            status_dim_style,
            &mut used,
            width,
        );
    }
    f.render_widget(Line::from(status_spans), status_area);

    app.poll_agent_runtime_states();
    if let (Some(sidebar_area), Some(active_key)) = (layout.sidebar, active_key.as_ref()) {
        let candidates = app.live_agent_switch_candidates();
        f.render_widget(Clear, sidebar_area);
        draw_agent_sidebar(
            f,
            app,
            sidebar_area,
            &candidates,
            active_key,
            app.agent_focus == AgentFocusPane::Sidebar,
        );
    }

    let modal_drawn = draw_input_modal(f, area, app);
    let ai_search_overlay_drawn =
        draw_ai_search_pending_overlay(f, area, app.ai_search_pending.as_ref());
    if !modal_drawn && !ai_search_overlay_drawn {
        if let Some(cursor) = focused_cursor {
            f.set_cursor_position(cursor);
        }
    }
}

fn draw_input_modal(f: &mut ratatui::Frame, area: Rect, app: &App) -> bool {
    if let Some(task) = app
        .data_task
        .as_ref()
        .filter(|task| task.kind == DataTaskKind::Clone)
    {
        draw_data_task_modal(f, area, task);
    } else if let InputMode::DeleteConfirm {
        info,
        removed_index: _,
        selected,
    } = &app.input_mode
    {
        draw_delete_confirm_modal(f, area, info, *selected, &app.keybindings);
    } else if let InputMode::CreateFolderConfirm {
        info,
        path,
        cols: _,
        rows: _,
        launch_mode: _,
        selected,
    } = &app.input_mode
    {
        draw_create_folder_confirm_modal(f, area, info, path, *selected, &app.keybindings);
    } else if let InputMode::RestoreDataConfirm {
        info,
        snapshot,
        cols: _,
        rows: _,
        launch_mode: _,
        selected,
    } = &app.input_mode
    {
        draw_restore_data_confirm_modal(f, area, info, snapshot, *selected, &app.keybindings);
    } else if let InputMode::SearchChoice { selected } = &app.input_mode {
        draw_search_choice_modal(f, area, *selected, &app.keybindings);
    } else if let InputMode::Filter { draft, cursor } = &app.input_mode {
        draw_filter_modal(
            f,
            area,
            draft,
            *cursor,
            app.search_pending.as_ref(),
            &app.keybindings,
        );
    } else if let InputMode::AiSearch { draft, cursor } = &app.input_mode {
        draw_ai_search_modal(
            f,
            area,
            draft,
            *cursor,
            app.ai_search_pending.as_ref(),
            &app.keybindings,
        );
    } else if let InputMode::AgentLaunch { source, selected } = &app.input_mode {
        draw_agent_launch_modal(
            f,
            area,
            source,
            *selected,
            &app.settings.cokacmux.agent_programs,
            &app.keybindings,
        );
    } else if let InputMode::CloneOptions {
        source,
        target,
        target_options: _,
        selected,
        folder_data,
    } = &app.input_mode
    {
        draw_clone_options_modal(
            f,
            area,
            source,
            *target,
            *selected,
            folder_data,
            &app.keybindings,
        );
    } else if let InputMode::NewSession {
        selected,
        kind,
        cwd,
        cwd_cursor,
        provider,
        provider_options,
        launch_mode,
    } = &app.input_mode
    {
        draw_new_session_modal(
            f,
            area,
            *selected,
            *kind,
            cwd,
            *cwd_cursor,
            *provider,
            provider_options,
            *launch_mode,
            &app.settings.cokacmux,
            &app.keybindings,
        );
    } else if let InputMode::TitleEdit {
        source,
        draft,
        cursor,
    } = &app.input_mode
    {
        let ai_title_pending = app
            .ai_title_pending
            .as_ref()
            .filter(|pending| pending.key == AgentKey::new(source));
        draw_title_edit_modal(
            f,
            area,
            source,
            draft,
            *cursor,
            ai_title_pending,
            &app.keybindings,
        );
    } else if let InputMode::Settings {
        state,
        return_to: _,
    } = &app.input_mode
    {
        draw_settings_modal(f, area, state, &app.keybindings);
    } else if let InputMode::Notice { title, message } = &app.input_mode {
        draw_notice_modal(f, area, title, message);
    } else {
        return false;
    }
    true
}

fn draw_notice_modal(f: &mut ratatui::Frame, area: Rect, title: &str, message: &str) {
    let help_items = [direct_help_item("Enter/Esc", "close")];
    let lines = vec![
        Line::from(Span::styled(
            message.to_string(),
            Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
        )),
        Line::from(""),
        modal_help_line(&help_items),
    ];
    let modal_area = modal_area_for_wrapped_lines(area, title, &lines, 40, 92, 5, 12);
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title(title.to_string());
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: true });
    f.render_widget(Clear, modal_area);
    f.render_widget(p, modal_area);
}

fn draw_data_task_modal(f: &mut ratatui::Frame, area: Rect, task: &DataTaskPending) {
    let elapsed = task.started_at.elapsed();
    let status = task
        .notice
        .as_deref()
        .or(task.progress_message.as_deref())
        .unwrap_or(&task.label);
    let mut lines: Vec<Line<'static>> = vec![
        Line::from(Span::styled(
            format!(
                "{} {}",
                startup_spinner_frame(elapsed),
                truncate_width(&task.label, 58)
            ),
            Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
        )),
        Line::from(Span::styled(
            format!("Status: {}", truncate_width(status, 60)),
            Style::default().fg(THEME_ACCENT).bg(THEME_BG_ALT),
        )),
        Line::from(Span::styled(
            format!("Elapsed: {}s", elapsed.as_secs()),
            Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
        )),
    ];

    if let Some(stats) = task.progress_stats.as_ref() {
        lines.push(Line::from(Span::styled(
            format!("Copied: {}", copy_stats_summary(stats)),
            Style::default().fg(THEME_FG).bg(THEME_BG_ALT),
        )));
    }
    if let Some(total) = task.progress_total.as_ref() {
        let percent = copy_percent_summary(task.progress_stats.as_ref(), Some(total))
            .unwrap_or_else(|| "0%".to_string());
        let copied = task
            .progress_stats
            .as_ref()
            .map(copy_stats_summary)
            .unwrap_or_else(|| "0 files, 0 dirs, 0 symlinks, 0 bytes".to_string());
        let total = copy_stats_summary(total);
        lines.push(Line::from(Span::styled(
            format!(
                "Progress: {}",
                truncate_width(&format!("{copied} of {total} ({percent})"), 58)
            ),
            Style::default().fg(THEME_FG).bg(THEME_BG_ALT),
        )));
    }
    if let Some(path) = task.progress_path.as_deref() {
        lines.push(Line::from(Span::styled(
            format!("Current: {}", truncate_width(path, 58)),
            Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
        )));
    }

    lines.push(Line::from(""));
    let help_items = if task.cancel_requested {
        [direct_help_item(
            "Esc",
            "pressed · cancelling and rolling back when safe",
        )]
    } else {
        [direct_help_item(
            "Esc",
            "cancel · all other actions locked until clone completes",
        )]
    };
    lines.push(modal_help_line(&help_items));

    let modal_area = modal_area_for_wrapped_lines(area, "Clone in progress", &lines, 44, 86, 7, 12);
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title("Clone in progress");
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: true });
    f.render_widget(Clear, modal_area);
    f.render_widget(p, modal_area);
}

fn agent_sidebar_width(total_width: u16, configured_width: u16) -> u16 {
    configured_width.min(total_width)
}

fn agent_terminal_width(total_width: u16, configured_width: u16) -> u16 {
    total_width.saturating_sub(agent_sidebar_width(total_width, configured_width))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct AgentViewport {
    area_cols: u16,
    area_rows: u16,
    pty_cols: u16,
    pty_rows: u16,
    page_rows: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct AgentPaneLayout {
    sidebar: Option<Rect>,
    main: Rect,
    auxiliary: Option<Rect>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct AgentViewports {
    main: AgentViewport,
    auxiliary: Option<AgentViewport>,
}

fn agent_viewport_for_terminal(
    total_width: u16,
    terminal_rows: u16,
    configured_sidebar_width: u16,
) -> AgentViewport {
    agent_viewports_for_terminal(
        total_width,
        terminal_rows,
        configured_sidebar_width,
        false,
        None,
    )
    .main
}

fn agent_viewports_for_terminal(
    total_width: u16,
    terminal_rows: u16,
    configured_sidebar_width: u16,
    auxiliary_visible: bool,
    configured_auxiliary_width: Option<u16>,
) -> AgentViewports {
    let area_rows = terminal_rows.saturating_sub(AGENT_STATUS_HEIGHT);
    let layout = agent_pane_layout_for_area(
        Rect::new(0, 0, total_width, area_rows),
        configured_sidebar_width,
        auxiliary_visible,
        configured_auxiliary_width,
    );
    AgentViewports {
        main: agent_viewport_for_pane_area(main_agent_content_area(layout.main), false),
        auxiliary: layout
            .auxiliary
            .map(|area| agent_viewport_for_pane_area(area, true)),
    }
}

fn agent_viewport_for_pane_area(area: Rect, framed: bool) -> AgentViewport {
    let content = if framed { pane_inner(area) } else { area };
    let (pty_rows, pty_cols) = agent_screen_size_for_area(content);
    AgentViewport {
        area_cols: content.width,
        area_rows: content.height,
        pty_cols,
        pty_rows,
        page_rows: content.height.max(1) as usize,
    }
}

fn agent_pane_layout_for_area(
    area: Rect,
    configured_sidebar_width: u16,
    auxiliary_visible: bool,
    configured_auxiliary_width: Option<u16>,
) -> AgentPaneLayout {
    let sidebar_width = agent_sidebar_width(area.width, configured_sidebar_width);
    let (sidebar, content_area) = if sidebar_width > 0 {
        let chunks = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([
                Constraint::Length(sidebar_width),
                Constraint::Length(area.width.saturating_sub(sidebar_width)),
            ])
            .split(area);
        (Some(chunks[0]), chunks[1])
    } else {
        (None, area)
    };

    if !auxiliary_visible || content_area.width <= 1 {
        return AgentPaneLayout {
            sidebar,
            main: content_area,
            auxiliary: None,
        };
    }

    let auxiliary_width = agent_auxiliary_width(content_area.width, configured_auxiliary_width);
    if auxiliary_width == 0 || auxiliary_width >= content_area.width {
        return AgentPaneLayout {
            sidebar,
            main: content_area,
            auxiliary: None,
        };
    }

    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Length(content_area.width.saturating_sub(auxiliary_width)),
            Constraint::Length(auxiliary_width),
        ])
        .split(content_area);
    AgentPaneLayout {
        sidebar,
        main: chunks[0],
        auxiliary: Some(chunks[1]),
    }
}

fn agent_auxiliary_width(content_width: u16, configured_width: Option<u16>) -> u16 {
    let (min_width, max_width) = agent_auxiliary_width_bounds(content_width);
    if min_width == 0 || max_width == 0 {
        return 0;
    }
    configured_width
        .unwrap_or_else(|| default_agent_auxiliary_width(content_width))
        .clamp(min_width, max_width)
}

fn default_agent_auxiliary_width(content_width: u16) -> u16 {
    let (min_width, max_width) = agent_auxiliary_width_bounds(content_width);
    if min_width == 0 || max_width == 0 {
        return 0;
    }
    let proportional = ((u32::from(content_width) * 2) / 5) as u16;
    proportional
        .clamp(min_width, AGENT_AUX_PANE_TARGET_WIDTH.min(max_width))
        .min(max_width)
}

fn agent_auxiliary_width_bounds(content_width: u16) -> (u16, u16) {
    if content_width <= 1 {
        return (0, 0);
    }
    if content_width <= AGENT_AUX_PANE_MIN_WIDTH.saturating_add(AGENT_MAIN_MIN_WIDTH_WITH_AUX) {
        let split = content_width / 2;
        return (split, split);
    }
    (
        AGENT_AUX_PANE_MIN_WIDTH,
        content_width.saturating_sub(AGENT_MAIN_MIN_WIDTH_WITH_AUX),
    )
}

fn agent_pty_size(cols: u16, rows: u16) -> PtySize {
    PtySize {
        rows: rows.max(AGENT_MIN_PTY_ROWS),
        cols: cols.max(AGENT_MIN_PTY_COLS),
        pixel_width: 0,
        pixel_height: 0,
    }
}

// vt100 0.16.2 has an unwrap() in Screen::text() that panics when a wide
// character is drawn at the last column (col+1 out of bounds). catch_unwind
// keeps the process alive, but the default panic hook still floods stderr —
// which destroys the TUI. Replace the hook so vt100 panics go to debug_log
// only; other panics keep the original behavior.
fn install_vt100_panic_filter() {
    let default_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let file = info.location().map(|l| l.file()).unwrap_or("");
        // Match any source file under the vt100 crate (screen.rs, grid.rs, ...)
        let is_vt100 = file.contains("vt100-");
        if is_vt100 {
            let payload = info.payload();
            let msg = payload
                .downcast_ref::<&str>()
                .copied()
                .or_else(|| payload.downcast_ref::<String>().map(String::as_str))
                .unwrap_or("<unknown>");
            debug_log(
                "vt100_panic_suppressed",
                serde_json::json!({
                    "file": file,
                    "line": info.location().map(|l| l.line()).unwrap_or(0),
                    "col": info.location().map(|l| l.column()).unwrap_or(0),
                    "message": msg,
                }),
            );
            return;
        }
        let payload = info.payload();
        let msg = payload
            .downcast_ref::<&str>()
            .copied()
            .or_else(|| payload.downcast_ref::<String>().map(String::as_str))
            .unwrap_or("<unknown>");
        debug_log(
            "panic_unhandled",
            serde_json::json!({
                "file": file,
                "line": info.location().map(|l| l.line()).unwrap_or(0),
                "col": info.location().map(|l| l.column()).unwrap_or(0),
                "message": msg,
            }),
        );
        // The async log writer may still hold queued lines; drain them so
        // crash diagnostics reach disk before the process dies.
        cokacmux::debug::flush(Duration::from_secs(2));
        default_hook(info);
    }));
}

fn safe_parser_process(parser: &mut vt100::Parser, bytes: &[u8]) -> bool {
    use std::panic::{catch_unwind, AssertUnwindSafe};
    let (cols, rows) = parser.screen().size();
    match catch_unwind(AssertUnwindSafe(|| parser.process(bytes))) {
        Ok(()) => true,
        Err(_) => {
            let dump_path = dump_vt100_panic_input(bytes, cols, rows);
            debug_log(
                "vt100_parser_panic",
                serde_json::json!({
                    "len": bytes.len(),
                    "cols": cols,
                    "rows": rows,
                    "sample": debug_bytes_sample(bytes, 128),
                    "dump": dump_path.as_ref().map(|p| p.display().to_string()),
                }),
            );
            false
        }
    }
}

/// Dump raw bytes that triggered a vt100 panic, plus the parser size, so we
/// can replay the exact input in a standalone reproducer.
fn dump_vt100_panic_input(bytes: &[u8], cols: u16, rows: u16) -> Option<PathBuf> {
    if !DEBUG_ENABLED.load(Ordering::Relaxed) {
        return None;
    }
    let dir = app_config_dir()?.join("debug").join("vt100_panics");
    fs::create_dir_all(&dir).ok()?;
    let seq = VT100_PANIC_DUMP_SEQ.fetch_add(1, Ordering::Relaxed);
    let now_ms = current_epoch_ms();
    let filename = format!("panic_{:013}_{:04}_c{}r{}.bin", now_ms, seq, cols, rows);
    let path = dir.join(filename);
    if fs::write(&path, bytes).is_err() {
        return None;
    }
    Some(path)
}

static VT100_PANIC_DUMP_SEQ: AtomicUsize = AtomicUsize::new(0);

fn screen_activity_hash(screen: &vt100::Screen) -> u64 {
    let mut hasher = DefaultHasher::new();
    let (rows, cols) = screen.size();
    rows.hash(&mut hasher);
    cols.hash(&mut hasher);
    for row in 0..rows {
        for col in 0..cols {
            let Some(cell) = screen.cell(row, col) else {
                "".hash(&mut hasher);
                continue;
            };
            if cell.is_wide_continuation() {
                continue;
            }
            if cell.has_contents() {
                cell.contents().hash(&mut hasher);
            } else {
                "".hash(&mut hasher);
            }
        }
    }
    hasher.finish()
}

fn screen_has_visible_content(screen: &vt100::Screen) -> bool {
    let (rows, cols) = screen.size();
    for row in 0..rows {
        for col in 0..cols {
            let Some(cell) = screen.cell(row, col) else {
                continue;
            };
            if cell.is_wide_continuation() || !cell.has_contents() {
                continue;
            }
            if !cell.contents().trim().is_empty() {
                return true;
            }
        }
    }
    false
}

fn sessions_pane_width(
    total_width: u16,
    configured_width: Option<u16>,
    fallback_percent: u16,
) -> u16 {
    let configured_width = configured_width.unwrap_or_else(|| {
        ((u32::from(total_width) * u32::from(fallback_percent.min(100))) / 100) as u16
    });
    configured_width.min(max_sessions_pane_width(total_width))
}

fn max_sessions_pane_width(total_width: u16) -> u16 {
    if total_width > MIN_PREVIEW_PANE_WIDTH {
        total_width - MIN_PREVIEW_PANE_WIDTH
    } else {
        total_width
    }
}

fn agent_screen_size_for_area(area: Rect) -> (u16, u16) {
    (
        area.height.max(AGENT_MIN_PTY_ROWS),
        area.width.max(AGENT_MIN_PTY_COLS),
    )
}

fn adjusted_visible_pane_width(current: u16, total_width: u16, delta: i16) -> (u16, bool) {
    let next = (current as i32 + delta as i32).clamp(0, total_width as i32) as u16;
    (next, next == current)
}

fn adjusted_sessions_pane_width(
    configured_width: Option<u16>,
    total_width: u16,
    fallback_percent: u16,
    delta: i16,
) -> (u16, bool) {
    adjusted_visible_pane_width(
        sessions_pane_width(total_width, configured_width, fallback_percent),
        max_sessions_pane_width(total_width),
        delta,
    )
}

fn adjusted_agent_sidebar_width(
    configured_width: u16,
    total_width: u16,
    delta: i16,
) -> (u16, bool) {
    adjusted_visible_pane_width(
        agent_sidebar_width(total_width, configured_width),
        total_width,
        delta,
    )
}

fn adjusted_agent_auxiliary_width(
    configured_width: Option<u16>,
    content_width: u16,
    delta: i16,
) -> (u16, bool) {
    let (min_width, max_width) = agent_auxiliary_width_bounds(content_width);
    if min_width == 0 || max_width == 0 {
        return (0, true);
    }
    let current = agent_auxiliary_width(content_width, configured_width);
    let next = (i32::from(current) + i32::from(delta))
        .clamp(i32::from(min_width), i32::from(max_width)) as u16;
    (next, next == current)
}

fn draw_agent_sidebar(
    f: &mut ratatui::Frame,
    app: &App,
    area: Rect,
    candidates: &[SessionInfo],
    active_key: &AgentKey,
    focused: bool,
) {
    let title = format!(" agents {} ", candidates.len());
    fill_area(f.buffer_mut(), area, theme_base_style());
    let border_color = if focused {
        THEME_BORDER_ACTIVE
    } else {
        THEME_BORDER
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(border_color))
        .style(theme_base_style())
        .title(title);
    f.render_widget(block, area);

    let inner = pane_inner(area);
    if inner.height == 0 || inner.width == 0 {
        return;
    }

    let id_width = inner
        .width
        .saturating_sub((STATE_COLUMN_WIDTH + PROVIDER_COLUMN_WIDTH + 3) as u16)
        as usize;
    let items: Vec<ListItem> = candidates
        .iter()
        .map(|info| {
            let key = AgentKey::new(info);
            let state = if key == *active_key {
                app.agent_state_for(info).attached_mine()
            } else {
                app.agent_state_for(info)
            };
            // Direct PTY tools use an arbitrary provider only for daemon
            // namespacing; render their actual tool kind instead.
            let (badge_span, label) = if is_plain_pty_tool_session_info(info) {
                let cwd_label = if info.cwd.is_empty() {
                    "(no cwd)".to_string()
                } else {
                    truncate_width(&info.cwd, id_width)
                };
                let badge = if is_cokacdir_session_info(info) {
                    cokacdir_badge_span()
                } else {
                    shell_badge_span()
                };
                (badge, cwd_label)
            } else {
                let title = info.title.as_deref().unwrap_or("");
                let label = if title.is_empty() {
                    truncate_width(&info.session_id, id_width)
                } else {
                    truncate_width(title, id_width)
                };
                (prov_span(info.provider), label)
            };
            ListItem::new(Line::from(vec![
                Span::styled(
                    fit_width(state.label(), STATE_COLUMN_WIDTH, Align::Left),
                    state.style(),
                ),
                Span::raw(" "),
                badge_span,
                Span::raw(" "),
                Span::styled(label, Style::default().fg(THEME_FG_STRONG)),
            ]))
        })
        .collect();

    let mut state = ListState::default();
    state.select(
        candidates
            .iter()
            .position(|info| AgentKey::new(info) == *active_key),
    );
    let list = List::new(items)
        .style(theme_base_style())
        .highlight_style(theme_selected_style())
        .highlight_symbol(UI_SELECTED_MARKER);
    f.render_stateful_widget(list, inner, &mut state);
}

fn render_vt100_screen(buf: &mut Buffer, screen: &vt100::Screen, area: Rect) {
    for row in 0..area.height {
        for col in 0..area.width {
            let Some(cell) = screen.cell(row, col) else {
                buf[(area.x + col, area.y + row)]
                    .set_symbol(" ")
                    .set_style(Style::default().bg(AGENT_DEFAULT_BG));
                continue;
            };
            if cell.is_wide_continuation() {
                continue;
            }
            let symbol = if cell.has_contents() {
                cell.contents()
            } else {
                " "
            };
            buf[(area.x + col, area.y + row)]
                .set_symbol(symbol)
                .set_style(vt100_cell_style(cell));
        }
    }
}

fn render_plain_agent_history(buf: &mut Buffer, area: Rect, lines: &[String]) {
    let style = Style::default().fg(THEME_FG).bg(AGENT_DEFAULT_BG);
    for (row, line) in lines.iter().take(area.height as usize).enumerate() {
        let y = area.y + row as u16;
        buf.set_stringn(
            area.x,
            y,
            truncate_width(line, area.width as usize),
            area.width as usize,
            style,
        );
    }
}

fn vt100_cell_style(cell: &vt100::Cell) -> Style {
    let mut style = Style::default()
        .fg(vt100_color(cell.fgcolor()))
        .bg(vt100_bg_color(cell.bgcolor()));
    if cell.bold() {
        style = style.add_modifier(Modifier::BOLD);
    }
    if cell.dim() {
        style = style.add_modifier(Modifier::DIM);
    }
    if cell.italic() {
        style = style.add_modifier(Modifier::ITALIC);
    }
    if cell.underline() {
        style = style.add_modifier(Modifier::UNDERLINED);
    }
    if cell.inverse() {
        style = style.add_modifier(Modifier::REVERSED);
    }
    style
}

fn vt100_bg_color(color: vt100::Color) -> Color {
    match color {
        vt100::Color::Default => AGENT_DEFAULT_BG,
        vt100::Color::Idx(index) => Color::Indexed(index),
        vt100::Color::Rgb(r, g, b) => Color::Indexed(rgb_to_ansi256(r, g, b)),
    }
}

fn vt100_color(color: vt100::Color) -> Color {
    match color {
        vt100::Color::Default => THEME_FG,
        vt100::Color::Idx(index) => Color::Indexed(index),
        vt100::Color::Rgb(r, g, b) => Color::Indexed(rgb_to_ansi256(r, g, b)),
    }
}

fn rgb_to_ansi256(r: u8, g: u8, b: u8) -> u8 {
    let (r, g, b) = (u16::from(r), u16::from(g), u16::from(b));
    let mut best_index = 16u8;
    let mut best_distance = u32::MAX;
    for index in 16u8..=255 {
        let (cr, cg, cb) = ansi256_rgb(index);
        let distance = color_distance(r, g, b, cr, cg, cb);
        if distance < best_distance {
            best_distance = distance;
            best_index = index;
        }
    }
    best_index
}

fn ansi256_rgb(index: u8) -> (u16, u16, u16) {
    if index >= 232 {
        let shade = 8 + u16::from(index - 232) * 10;
        return (shade, shade, shade);
    }

    let cube_index = index - 16;
    let r = cube_index / 36;
    let g = (cube_index % 36) / 6;
    let b = cube_index % 6;
    (
        ansi256_cube_component(r),
        ansi256_cube_component(g),
        ansi256_cube_component(b),
    )
}

fn ansi256_cube_component(value: u8) -> u16 {
    if value == 0 {
        0
    } else {
        55 + u16::from(value) * 40
    }
}

fn color_distance(r: u16, g: u16, b: u16, cr: u16, cg: u16, cb: u16) -> u32 {
    let dr = i32::from(r) - i32::from(cr);
    let dg = i32::from(g) - i32::from(cg);
    let db = i32::from(b) - i32::from(cb);
    (dr * dr + dg * dg + db * db) as u32
}

fn handle_key(app: &mut App, key: KeyEvent, total_width: u16, agent_cols: u16, agent_rows: u16) {
    let keybindings = app.keybindings.clone();
    debug_log_session_key(app, key, "received");
    if handle_ai_search_locked_key(app, key) {
        return;
    }
    if app.handle_data_task_key(key) {
        return;
    }
    if keybindings.matches(KeyAction::GlobalQuit, key) {
        if app.request_quit("global_quit", false) {
            debug_log_session_key(app, key, "global_quit");
        } else {
            debug_log_session_key(app, key, "global_quit_blocked");
        }
        return;
    }
    if handle_notice_key(app, key) {
        return;
    }

    // Search mode chooser
    if let InputMode::SearchChoice { selected } = &mut app.input_mode {
        let mut next_mode: Option<InputMode> = None;
        let mut search_choice: Option<SearchChoice> = None;
        if keybindings.matches(KeyAction::SearchChoiceCancel, key) {
            next_mode = Some(InputMode::Normal);
            app.status = "cancelled.".into();
            debug_log_key_event(key, "search_choice_cancel");
        } else if keybindings.matches(KeyAction::SearchChoiceConfirm, key) {
            search_choice = Some(search_choice_at(*selected));
            debug_log(
                "search_choice_confirm",
                serde_json::json!({
                    "selected": *selected,
                    "choice": search_choice_label(search_choice_at(*selected)),
                }),
            );
        } else if keybindings.matches(KeyAction::SearchChoiceNext, key) {
            *selected = move_search_choice_index(*selected, 1);
            debug_log(
                "search_choice_move",
                serde_json::json!({
                    "selected": *selected,
                    "choice": search_choice_label(search_choice_at(*selected)),
                }),
            );
        } else if keybindings.matches(KeyAction::SearchChoicePrev, key) {
            *selected = move_search_choice_index(*selected, -1);
            debug_log(
                "search_choice_move",
                serde_json::json!({
                    "selected": *selected,
                    "choice": search_choice_label(search_choice_at(*selected)),
                }),
            );
        } else if keybindings.matches(KeyAction::SearchChoiceText, key) {
            *selected = SEARCH_CHOICE_TEXT;
            search_choice = Some(SearchChoice::Text);
            debug_log_key_event(key, "search_choice_text");
        } else if keybindings.matches(KeyAction::SearchChoiceAi, key) {
            *selected = SEARCH_CHOICE_AI;
            search_choice = Some(SearchChoice::Ai);
            debug_log_key_event(key, "search_choice_ai");
        } else {
            debug_log_key_event(key, "search_choice_ignored");
        }

        if let Some(mode) = next_mode {
            app.input_mode = mode;
        }
        if let Some(choice) = search_choice {
            match choice {
                SearchChoice::Text => app.begin_filter(),
                SearchChoice::Ai => app.begin_ai_search(),
            }
        }
        return;
    }

    // Delete confirmation dialog
    if let InputMode::DeleteConfirm {
        info,
        removed_index,
        selected,
    } = &mut app.input_mode
    {
        let mut next_mode: Option<InputMode> = None;
        let mut delete_action: Option<(SessionInfo, Option<usize>)> = None;
        let choose_option = |option: DeleteOption,
                             info: &SessionInfo,
                             removed_index: Option<usize>,
                             delete_action: &mut Option<(SessionInfo, Option<usize>)>,
                             next_mode: &mut Option<InputMode>| {
            match option {
                DeleteOption::Delete => {
                    *delete_action = Some((info.clone(), removed_index));
                    *next_mode = Some(InputMode::Normal);
                }
                DeleteOption::Cancel => {
                    *next_mode = Some(InputMode::Normal);
                }
            }
        };

        if keybindings.matches(KeyAction::DeleteConfirmCancel, key)
            || keybindings.matches(KeyAction::DeleteConfirmCancelChoice, key)
        {
            next_mode = Some(InputMode::Normal);
            app.status = "cancelled.".into();
            debug_log_key_event(key, "delete_confirm_cancel");
        } else if keybindings.matches(KeyAction::DeleteConfirmConfirm, key) {
            let option = delete_option_at(*selected);
            if option == DeleteOption::Cancel {
                app.status = "cancelled.".into();
            }
            choose_option(
                option,
                info,
                *removed_index,
                &mut delete_action,
                &mut next_mode,
            );
            debug_log(
                "delete_confirm_confirm",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::DeleteConfirmNext, key) {
            *selected = move_delete_option_index(*selected, 1);
            debug_log(
                "delete_confirm_move",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::DeleteConfirmPrev, key) {
            *selected = move_delete_option_index(*selected, -1);
            debug_log(
                "delete_confirm_move",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::DeleteConfirmDelete, key) {
            *selected = DELETE_OPTION_DELETE;
            choose_option(
                DeleteOption::Delete,
                info,
                *removed_index,
                &mut delete_action,
                &mut next_mode,
            );
        } else {
            debug_log_key_event(key, "delete_confirm_ignored");
        }

        if let Some(mode) = next_mode {
            app.input_mode = mode;
        }
        if let Some((info, removed_index)) = delete_action {
            app.delete_session(info, removed_index);
        }
        return;
    }
    // Create missing launch folder dialog
    if let InputMode::CreateFolderConfirm {
        info,
        path,
        cols,
        rows,
        launch_mode,
        selected,
    } = &mut app.input_mode
    {
        let mut next_mode: Option<InputMode> = None;
        let mut create_action: Option<(SessionInfo, PathBuf, u16, u16, AgentLaunchMode)> = None;
        let choose_option =
            |option: CreateFolderOption,
             info: &SessionInfo,
             path: &Path,
             cols: u16,
             rows: u16,
             launch_mode: AgentLaunchMode,
             create_action: &mut Option<(SessionInfo, PathBuf, u16, u16, AgentLaunchMode)>,
             next_mode: &mut Option<InputMode>| {
                match option {
                    CreateFolderOption::Create => {
                        *create_action =
                            Some((info.clone(), path.to_path_buf(), cols, rows, launch_mode));
                        *next_mode = Some(InputMode::Normal);
                    }
                    CreateFolderOption::Cancel => {
                        *next_mode = Some(InputMode::Normal);
                    }
                }
            };

        if keybindings.matches(KeyAction::CreateFolderCancel, key)
            || keybindings.matches(KeyAction::CreateFolderCancelChoice, key)
        {
            next_mode = Some(InputMode::Normal);
            app.status = "cancelled.".into();
            debug_log_key_event(key, "create_folder_cancel");
        } else if keybindings.matches(KeyAction::CreateFolderConfirm, key) {
            let option = create_folder_option_at(*selected);
            if option == CreateFolderOption::Cancel {
                app.status = "cancelled.".into();
            }
            choose_option(
                option,
                info,
                path,
                *cols,
                *rows,
                *launch_mode,
                &mut create_action,
                &mut next_mode,
            );
            debug_log(
                "create_folder_confirm",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                    "cwd": path.display().to_string(),
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::CreateFolderNext, key) {
            *selected = move_create_folder_option_index(*selected, 1);
            debug_log(
                "create_folder_move",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::CreateFolderPrev, key) {
            *selected = move_create_folder_option_index(*selected, -1);
            debug_log(
                "create_folder_move",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::CreateFolderCreate, key) {
            *selected = CREATE_FOLDER_OPTION_CREATE;
            choose_option(
                CreateFolderOption::Create,
                info,
                path,
                *cols,
                *rows,
                *launch_mode,
                &mut create_action,
                &mut next_mode,
            );
        } else {
            debug_log_key_event(key, "create_folder_ignored");
        }

        if let Some(mode) = next_mode {
            app.input_mode = mode;
        }
        if let Some((info, path, cols, rows, launch_mode)) = create_action {
            app.create_missing_launch_cwd_and_attach(info, path, cols, rows, launch_mode);
        }
        return;
    }
    // Restore cloned folder data dialog
    if let InputMode::RestoreDataConfirm {
        info,
        snapshot,
        cols,
        rows,
        launch_mode,
        selected,
    } = &mut app.input_mode
    {
        let mut next_mode: Option<InputMode> = None;
        let mut restore_action: Option<(SessionInfo, u16, u16, AgentLaunchMode)> = None;
        let mut skip_action: Option<(SessionInfo, u16, u16, AgentLaunchMode)> = None;
        let choose_option =
            |option: RestoreDataOption,
             info: &SessionInfo,
             cols: u16,
             rows: u16,
             launch_mode: AgentLaunchMode,
             restore_action: &mut Option<(SessionInfo, u16, u16, AgentLaunchMode)>,
             skip_action: &mut Option<(SessionInfo, u16, u16, AgentLaunchMode)>,
             next_mode: &mut Option<InputMode>| {
                match option {
                    RestoreDataOption::Restore => {
                        *restore_action = Some((info.clone(), cols, rows, launch_mode));
                        *next_mode = Some(InputMode::Normal);
                    }
                    RestoreDataOption::StartWithoutRestore => {
                        *skip_action = Some((info.clone(), cols, rows, launch_mode));
                        *next_mode = Some(InputMode::Normal);
                    }
                }
            };

        if keybindings.matches(KeyAction::RestoreDataSkip, key)
            || keybindings.matches(KeyAction::RestoreDataSkipChoice, key)
        {
            next_mode = Some(InputMode::Normal);
            skip_action = Some((info.clone(), *cols, *rows, *launch_mode));
            debug_log_key_event(key, "restore_data_skip");
        } else if keybindings.matches(KeyAction::RestoreDataConfirm, key) {
            let option = restore_data_option_at(*selected);
            choose_option(
                option,
                info,
                *cols,
                *rows,
                *launch_mode,
                &mut restore_action,
                &mut skip_action,
                &mut next_mode,
            );
            debug_log(
                "restore_data_confirm",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                    "snapshot_path": snapshot.snapshot_path.display().to_string(),
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::RestoreDataNext, key) {
            *selected = move_restore_data_option_index(*selected, 1);
            debug_log(
                "restore_data_move",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::RestoreDataPrev, key) {
            *selected = move_restore_data_option_index(*selected, -1);
            debug_log(
                "restore_data_move",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::RestoreDataRestore, key) {
            *selected = RESTORE_DATA_OPTION_RESTORE;
            choose_option(
                RestoreDataOption::Restore,
                info,
                *cols,
                *rows,
                *launch_mode,
                &mut restore_action,
                &mut skip_action,
                &mut next_mode,
            );
        } else {
            debug_log_key_event(key, "restore_data_ignored");
        }

        if let Some(mode) = next_mode {
            app.input_mode = mode;
        }
        if let Some((info, cols, rows, launch_mode)) = restore_action {
            app.restore_cloned_session_data_and_attach(info, cols, rows, launch_mode);
        } else if let Some((info, cols, rows, launch_mode)) = skip_action {
            app.attach_agent_without_data_restore_prompt(info, cols, rows, launch_mode);
        }
        return;
    }
    // Clone option dialog
    if let InputMode::CloneOptions {
        source,
        target,
        target_options,
        selected,
        folder_data,
    } = &mut app.input_mode
    {
        let mut next_mode: Option<InputMode> = None;
        let mut clone_action: Option<(SessionInfo, Provider, bool)> = None;
        let mut unavailable_reason: Option<String> = None;
        let choose_option = |option: CloneOption,
                             source: &SessionInfo,
                             target: Provider,
                             folder_data: &CloneFolderDataAvailability,
                             clone_action: &mut Option<(SessionInfo, Provider, bool)>,
                             unavailable_reason: &mut Option<String>,
                             next_mode: &mut Option<InputMode>| {
            match option {
                CloneOption::SessionOnly => {
                    *clone_action = Some((source.clone(), target, false));
                    *next_mode = Some(InputMode::Normal);
                }
                CloneOption::FolderData => {
                    if let Some(reason) = folder_data.unavailable_reason() {
                        *unavailable_reason = Some(reason.to_string());
                    } else {
                        *clone_action = Some((source.clone(), target, true));
                        *next_mode = Some(InputMode::Normal);
                    }
                }
                CloneOption::Cancel => {
                    *next_mode = Some(InputMode::Normal);
                }
            }
        };

        if keybindings.matches(KeyAction::CloneOptionsCancel, key)
            || keybindings.matches(KeyAction::CloneOptionsCancelChoice, key)
        {
            next_mode = Some(InputMode::Normal);
            app.status = "cancelled.".into();
            debug_log_key_event(key, "clone_options_cancel");
        } else if keybindings.matches(KeyAction::CloneOptionsConfirm, key) {
            let option = clone_option_at(*selected);
            if option == CloneOption::Cancel {
                app.status = "cancelled.".into();
            }
            choose_option(
                option,
                source,
                *target,
                folder_data,
                &mut clone_action,
                &mut unavailable_reason,
                &mut next_mode,
            );
            debug_log(
                "clone_options_confirm",
                serde_json::json!({
                    "source_provider": source.provider.as_str(),
                    "source_session_id": &source.session_id,
                    "target_provider": target.as_str(),
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::CloneOptionsTargetNext, key) {
            *target = move_provider_in_options(*target, 1, target_options);
            debug_log(
                "clone_options_target_move",
                serde_json::json!({
                    "source_provider": source.provider.as_str(),
                    "source_session_id": &source.session_id,
                    "target_provider": target.as_str(),
                }),
            );
        } else if keybindings.matches(KeyAction::CloneOptionsTargetPrev, key) {
            *target = move_provider_in_options(*target, -1, target_options);
            debug_log(
                "clone_options_target_move",
                serde_json::json!({
                    "source_provider": source.provider.as_str(),
                    "source_session_id": &source.session_id,
                    "target_provider": target.as_str(),
                }),
            );
        } else if keybindings.matches(KeyAction::CloneOptionsNext, key) {
            *selected = move_clone_option_index(*selected, 1);
            debug_log(
                "clone_options_move",
                serde_json::json!({
                    "source_provider": source.provider.as_str(),
                    "source_session_id": &source.session_id,
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::CloneOptionsPrev, key) {
            *selected = move_clone_option_index(*selected, -1);
            debug_log(
                "clone_options_move",
                serde_json::json!({
                    "source_provider": source.provider.as_str(),
                    "source_session_id": &source.session_id,
                    "selected": *selected,
                }),
            );
        } else if keybindings.matches(KeyAction::CloneOptionsSessionOnly, key) {
            *selected = CLONE_OPTION_SESSION_ONLY;
            choose_option(
                CloneOption::SessionOnly,
                source,
                *target,
                folder_data,
                &mut clone_action,
                &mut unavailable_reason,
                &mut next_mode,
            );
        } else if keybindings.matches(KeyAction::CloneOptionsFolderData, key) {
            *selected = CLONE_OPTION_FOLDER_DATA;
            choose_option(
                CloneOption::FolderData,
                source,
                *target,
                folder_data,
                &mut clone_action,
                &mut unavailable_reason,
                &mut next_mode,
            );
        } else {
            debug_log_key_event(key, "clone_options_ignored");
        }

        if let Some(reason) = unavailable_reason {
            app.status = format!(
                "folder data cannot be copied: {}",
                truncate_width(&reason, 72)
            );
            debug_log(
                "clone_options_folder_data_blocked",
                serde_json::json!({
                    "source_provider": source.provider.as_str(),
                    "source_session_id": &source.session_id,
                    "target_provider": target.as_str(),
                    "error": reason,
                }),
            );
        }
        if let Some(mode) = next_mode {
            app.input_mode = mode;
        }
        if let Some((source, target, copy_folder_data)) = clone_action {
            app.clone_session_to(source, target, copy_folder_data);
        }
        return;
    }
    // Settings dialog
    if let InputMode::Settings { state, return_to } = &mut app.input_mode {
        let mut next_mode: Option<InputMode> = None;
        let mut save_request: Option<(SettingsDraft, AiTitleSettingsReturn)> = None;
        if let Some(mut edit) = state.editing.take() {
            if keybindings.matches(KeyAction::AiTitleSettingsCancel, key) {
                state.cancel_editing_selected_text(edit);
                app.status = "path edit cancelled.".into();
                debug_log_key_event(key, "settings_path_edit_cancel");
            } else if keybindings.matches(KeyAction::AiTitleSettingsSave, key) {
                state.finish_editing_selected_text();
                app.status = "path edit done; Enter saves settings.".into();
                debug_log_key_event(key, "settings_path_edit_done");
            } else {
                {
                    let value = state.draft.text_field_value_mut(edit.field);
                    match key.code {
                        KeyCode::Left => {
                            edit.cursor = prev_char_boundary(value, edit.cursor);
                            debug_log_key_event(key, "settings_path_left");
                        }
                        KeyCode::Right => {
                            edit.cursor = next_char_boundary(value, edit.cursor);
                            debug_log_key_event(key, "settings_path_right");
                        }
                        KeyCode::Home => {
                            edit.cursor = 0;
                            debug_log_key_event(key, "settings_path_home");
                        }
                        KeyCode::End => {
                            edit.cursor = value.len();
                            debug_log_key_event(key, "settings_path_end");
                        }
                        KeyCode::Backspace => {
                            delete_before_cursor(value, &mut edit.cursor);
                            debug_log_key_event(key, "settings_path_backspace");
                        }
                        KeyCode::Delete => {
                            delete_at_cursor(value, &mut edit.cursor);
                            debug_log_key_event(key, "settings_path_delete");
                        }
                        KeyCode::Char(c)
                            if !key.modifiers.contains(KeyModifiers::CONTROL)
                                && !key.modifiers.contains(KeyModifiers::ALT) =>
                        {
                            insert_at_cursor(value, &mut edit.cursor, c);
                            debug_log_key_event(key, "settings_path_insert");
                        }
                        _ => {
                            debug_log_key_event(key, "settings_path_ignored");
                        }
                    }
                }
                state.editing = Some(edit);
            }
        } else if keybindings.matches(KeyAction::AiTitleSettingsCancel, key) {
            next_mode = Some(return_to.clone().into_input_mode());
            app.status = "cancelled.".into();
            debug_log_key_event(key, "settings_cancel");
        } else if keybindings.matches(KeyAction::AiTitleSettingsSave, key) {
            if state.selected_text_field().is_some() && !state.edit_finished {
                state.begin_editing_selected_text();
                app.status = "editing path; Enter finishes edit, Esc cancels edit.".into();
                debug_log_key_event(key, "settings_path_edit_begin");
            } else {
                save_request = Some((state.draft.clone(), return_to.clone()));
                debug_log(
                    "settings_save",
                    serde_json::json!({
                        "section": state.section.label(),
                        "provider": ai_title_provider_label(state.draft.ai_provider),
                    }),
                );
            }
        } else if key.code == KeyCode::Left {
            state.move_section(-1);
            app.status = format!("settings: {}", state.section.label());
            debug_log_key_event(key, "settings_section_prev");
        } else if key.code == KeyCode::Right {
            state.move_section(1);
            app.status = format!("settings: {}", state.section.label());
            debug_log_key_event(key, "settings_section_next");
        } else if keybindings.matches(KeyAction::AiTitleSettingsNext, key) {
            state.move_row(1);
            debug_log_key_event(key, "settings_row_next");
        } else if keybindings.matches(KeyAction::AiTitleSettingsPrev, key) {
            state.move_row(-1);
            debug_log_key_event(key, "settings_row_prev");
        } else if keybindings.matches(KeyAction::AiTitleSettingsNone, key) {
            state.section = SettingsSection::Ai;
            state.selected = SETTINGS_AI_NONE;
            state.draft.ai_provider = None;
            state.edit_finished = false;
            app.status = "AI agent: none".into();
        } else if keybindings.matches(KeyAction::AiTitleSettingsClaude, key) {
            state.section = SettingsSection::Ai;
            state.selected = SETTINGS_AI_CLAUDE;
            state.draft.ai_provider = Some(Provider::Claude);
            state.edit_finished = false;
            app.status = "AI agent: claude".into();
        } else if keybindings.matches(KeyAction::AiTitleSettingsCodex, key) {
            state.section = SettingsSection::Ai;
            state.selected = SETTINGS_AI_CODEX;
            state.draft.ai_provider = Some(Provider::Codex);
            state.edit_finished = false;
            app.status = "AI agent: codex".into();
        } else if keybindings.matches(KeyAction::AiTitleSettingsOpenCode, key) {
            state.section = SettingsSection::Ai;
            state.selected = SETTINGS_AI_OPENCODE;
            state.draft.ai_provider = Some(Provider::OpenCode);
            state.edit_finished = false;
            app.status = "AI agent: opencode".into();
        } else if matches!(key.code, KeyCode::Char(' ')) {
            app.status = state.activate_selected().into();
            debug_log_key_event(key, "settings_activate");
        } else if let KeyCode::Char(c) = key.code {
            if !key.modifiers.contains(KeyModifiers::CONTROL)
                && !key.modifiers.contains(KeyModifiers::ALT)
                && state.insert_char_in_selected_text(c)
            {
                app.status = "editing path; Enter finishes edit, Esc cancels edit.".into();
                debug_log_key_event(key, "settings_path_edit_begin_insert");
            } else {
                debug_log_key_event(key, "settings_ignored");
            }
        } else {
            debug_log_key_event(key, "settings_ignored");
        }
        if let Some(mode) = next_mode {
            app.input_mode = mode;
        }
        if let Some((draft, return_to)) = save_request {
            if app.save_settings_draft(draft) {
                app.input_mode = return_to.into_input_mode();
            }
        }
        return;
    }
    // New session dialog
    if matches!(app.input_mode, InputMode::NewSession { .. }) {
        handle_new_session_key(app, key, agent_cols.max(1), agent_rows.max(1), &keybindings);
        return;
    }
    // Agent launch mode selection
    if let InputMode::AgentLaunch { source, selected } = &mut app.input_mode {
        let mut next_mode: Option<InputMode> = None;
        let mut attach_action: Option<(SessionInfo, AgentLaunchMode)> = None;
        if keybindings.matches(KeyAction::AgentLaunchCancel, key) {
            next_mode = Some(InputMode::Normal);
            app.status = "cancelled.".into();
            debug_log_session_key(app, key, "agent_launch_cancel");
        } else if keybindings.matches(KeyAction::AgentLaunchConfirm, key) {
            let launch_mode = agent_launch_mode_at(*selected);
            next_mode = Some(InputMode::Normal);
            attach_action = Some((source.clone(), launch_mode));
            debug_log(
                "agent_launch_confirm",
                serde_json::json!({
                    "provider": source.provider.as_str(),
                    "session_id": &source.session_id,
                    "launch_mode": launch_mode.as_str(),
                }),
            );
        } else if keybindings.matches(KeyAction::AgentLaunchNext, key) {
            *selected = move_agent_launch_mode_index(*selected, 1);
            debug_log(
                "agent_launch_move",
                serde_json::json!({
                    "selected": *selected,
                    "launch_mode": agent_launch_mode_at(*selected).as_str(),
                }),
            );
        } else if keybindings.matches(KeyAction::AgentLaunchPrev, key) {
            *selected = move_agent_launch_mode_index(*selected, -1);
            debug_log(
                "agent_launch_move",
                serde_json::json!({
                    "selected": *selected,
                    "launch_mode": agent_launch_mode_at(*selected).as_str(),
                }),
            );
        } else if keybindings.matches(KeyAction::AgentLaunchNormal, key) {
            *selected = 0;
            debug_log_key_event(key, "agent_launch_select_normal");
        } else if keybindings.matches(KeyAction::AgentLaunchSkipPermissions, key) {
            *selected = 1;
            debug_log_key_event(key, "agent_launch_select_skip_permissions");
        } else {
            debug_log_key_event(key, "agent_launch_ignored");
        }
        if let Some(mode) = next_mode {
            app.input_mode = mode;
        }
        if let Some((source, launch_mode)) = attach_action {
            app.attach_agent(source, agent_cols.max(1), agent_rows.max(1), launch_mode);
        }
        return;
    }
    // Title edit mode
    if let InputMode::TitleEdit {
        source,
        draft,
        cursor,
    } = &mut app.input_mode
    {
        let mut next_mode: Option<InputMode> = None;
        let mut save_action: Option<(SessionInfo, String)> = None;
        let mut ai_title_action: Option<SessionInfo> = None;
        let ai_title_running_for_title = app
            .ai_title_pending
            .as_ref()
            .is_some_and(|pending| pending.key == AgentKey::new(source));
        if keybindings.matches(KeyAction::TitleCancel, key) {
            next_mode = Some(InputMode::Normal);
            app.status = "cancelled.".into();
            debug_log(
                "title_edit_cancel",
                serde_json::json!({
                    "provider": source.provider.as_str(),
                    "session_id": &source.session_id,
                    "draft_len": draft.len(),
                    "cursor": *cursor,
                }),
            );
        } else if ai_title_running_for_title
            && !keybindings.matches(KeyAction::TitleAiGenerate, key)
        {
            app.status = "AI title is running; title editing is paused.".into();
            debug_log(
                "title_edit_paused_for_ai_title",
                serde_json::json!({
                    "provider": source.provider.as_str(),
                    "session_id": &source.session_id,
                    "draft_len": draft.len(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::TitleSave, key) {
            save_action = Some((source.clone(), draft.clone()));
            next_mode = Some(InputMode::Normal);
            debug_log(
                "title_edit_commit",
                serde_json::json!({
                    "provider": source.provider.as_str(),
                    "session_id": &source.session_id,
                    "draft_len": draft.len(),
                }),
            );
        } else if keybindings.matches(KeyAction::TitleMoveLeft, key) {
            *cursor = prev_char_boundary(draft, *cursor);
            debug_log_title_edit_cursor(source, draft, *cursor, "left");
        } else if keybindings.matches(KeyAction::TitleMoveRight, key) {
            *cursor = next_char_boundary(draft, *cursor);
            debug_log_title_edit_cursor(source, draft, *cursor, "right");
        } else if keybindings.matches(KeyAction::TitleHome, key) {
            *cursor = 0;
            debug_log_title_edit_cursor(source, draft, *cursor, "home");
        } else if keybindings.matches(KeyAction::TitleEnd, key) {
            *cursor = draft.len();
            debug_log_title_edit_cursor(source, draft, *cursor, "end");
        } else if keybindings.matches(KeyAction::TitleBackspace, key) {
            delete_before_cursor(draft, cursor);
            debug_log_title_edit_cursor(source, draft, *cursor, "backspace");
        } else if keybindings.matches(KeyAction::TitleDelete, key) {
            delete_at_cursor(draft, cursor);
            debug_log_title_edit_cursor(source, draft, *cursor, "delete");
        } else if keybindings.matches(KeyAction::TitleAiGenerate, key) {
            if app.ai_title_pending.is_some() {
                app.status = "AI title already running.".into();
                debug_log_key_event(key, "title_ai_generate_pending");
            } else if app.settings.cokacmux.ai.provider.is_none() {
                next_mode = Some(InputMode::Settings {
                    state: SettingsState::new(&app.settings.cokacmux),
                    return_to: AiTitleSettingsReturn::TitleEdit {
                        source: source.clone(),
                        draft: draft.clone(),
                        cursor: *cursor,
                    },
                });
                app.status = "choose AI title agent before generating.".into();
                debug_log_key_event(key, "title_ai_generate_needs_settings");
            } else {
                ai_title_action = Some(source.clone());
                debug_log(
                    "title_ai_generate",
                    serde_json::json!({
                        "provider": app.settings.cokacmux.ai.provider.map(|p| p.as_str()),
                        "source_provider": source.provider.as_str(),
                        "session_id": &source.session_id,
                    }),
                );
            }
        } else if let KeyCode::Char(c) = key.code {
            if !key.modifiers.contains(KeyModifiers::CONTROL)
                && !key.modifiers.contains(KeyModifiers::ALT)
            {
                insert_at_cursor(draft, cursor, c);
                debug_log_title_edit_cursor(source, draft, *cursor, "insert");
            } else {
                debug_log_key_event(key, "title_edit_ignored");
            }
        } else {
            debug_log_key_event(key, "title_edit_ignored");
        }
        if let Some(mode) = next_mode {
            app.input_mode = mode;
        }
        if let Some((source, title)) = save_action {
            app.set_session_title(source, title);
        }
        if let Some(source) = ai_title_action {
            app.start_ai_title_generation(source);
        }
        return;
    }
    // AI search prompt mode
    let ai_search_is_searching = app.ai_search_pending.is_some();
    if let InputMode::AiSearch { draft, cursor } = &mut app.input_mode {
        let mut next_mode: Option<InputMode> = None;
        let mut apply_query: Option<String> = None;
        let mut quit_after_search: Option<bool> = None;
        if keybindings.matches(KeyAction::FilterCancel, key) {
            next_mode = Some(InputMode::Normal);
            app.status = "cancelled.".into();
            debug_log(
                "ai_search_cancel",
                serde_json::json!({
                    "draft_len": draft.chars().count(),
                    "searching": ai_search_is_searching,
                }),
            );
        } else if ai_search_is_searching
            && (keybindings.matches(KeyAction::GlobalQuit, key)
                || keybindings.matches(KeyAction::SessionQuit, key))
        {
            next_mode = Some(InputMode::Normal);
            quit_after_search = Some(false);
            debug_log_key_event(key, "ai_search_searching_quit");
        } else if ai_search_is_searching && keybindings.matches(KeyAction::SessionForceQuit, key) {
            next_mode = Some(InputMode::Normal);
            quit_after_search = Some(true);
            debug_log_key_event(key, "ai_search_searching_force_quit");
        } else if ai_search_is_searching {
            debug_log_key_event(key, "ai_search_searching_ignored");
        } else if keybindings.matches(KeyAction::FilterApply, key) {
            if !draft.trim().is_empty() && app.settings.cokacmux.ai.provider.is_none() {
                next_mode = Some(InputMode::Settings {
                    state: SettingsState::new(&app.settings.cokacmux),
                    return_to: AiTitleSettingsReturn::AiSearch {
                        draft: draft.clone(),
                        cursor: *cursor,
                    },
                });
                app.status = "choose AI agent before searching.".into();
                debug_log_key_event(key, "ai_search_needs_settings");
            } else {
                apply_query = Some(draft.clone());
            }
        } else if keybindings.matches(KeyAction::FilterMoveLeft, key) {
            *cursor = prev_char_boundary(draft, *cursor);
            debug_log(
                "ai_search_cursor",
                serde_json::json!({
                    "action": "left",
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::FilterMoveRight, key) {
            *cursor = next_char_boundary(draft, *cursor);
            debug_log(
                "ai_search_cursor",
                serde_json::json!({
                    "action": "right",
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::FilterHome, key) {
            *cursor = 0;
            debug_log(
                "ai_search_cursor",
                serde_json::json!({
                    "action": "home",
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::FilterEnd, key) {
            *cursor = draft.len();
            debug_log(
                "ai_search_cursor",
                serde_json::json!({
                    "action": "end",
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::FilterBackspace, key) {
            delete_before_cursor(draft, cursor);
            debug_log(
                "ai_search_backspace",
                serde_json::json!({
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::FilterDelete, key) {
            delete_at_cursor(draft, cursor);
            debug_log(
                "ai_search_delete",
                serde_json::json!({
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if let KeyCode::Char(c) = key.code {
            if !key.modifiers.contains(KeyModifiers::CONTROL)
                && !key.modifiers.contains(KeyModifiers::ALT)
            {
                insert_at_cursor(draft, cursor, c);
                debug_log(
                    "ai_search_insert",
                    serde_json::json!({
                        "draft_len": draft.chars().count(),
                        "cursor": *cursor,
                    }),
                );
            } else {
                debug_log_key_event(key, "ai_search_ignored");
            }
        } else {
            debug_log_key_event(key, "ai_search_ignored");
        }
        if let Some(mode) = next_mode {
            app.input_mode = mode;
        }
        if let Some(force) = quit_after_search {
            app.request_quit("ai_search_searching_quit", force);
            return;
        }
        if let Some(query) = apply_query {
            app.start_ai_search(query);
        }
        return;
    }
    // Filter input mode
    let filter_is_searching = app.search_pending.is_some();
    if let InputMode::Filter { draft, cursor } = &mut app.input_mode {
        let mut next_mode: Option<InputMode> = None;
        let mut apply_query: Option<String> = None;
        let mut cancel_search_reason: Option<&'static str> = None;
        let mut quit_after_filter: Option<bool> = None;
        if keybindings.matches(KeyAction::FilterCancel, key) {
            next_mode = Some(InputMode::Normal);
            cancel_search_reason = Some("cancel");
            app.status = "cancelled.".into();
            debug_log(
                "filter_cancel",
                serde_json::json!({
                    "draft_len": draft.chars().count(),
                    "searching": filter_is_searching,
                }),
            );
        } else if filter_is_searching
            && (keybindings.matches(KeyAction::GlobalQuit, key)
                || keybindings.matches(KeyAction::SessionQuit, key))
        {
            next_mode = Some(InputMode::Normal);
            cancel_search_reason = Some("quit");
            quit_after_filter = Some(false);
            debug_log_key_event(key, "filter_searching_quit");
        } else if filter_is_searching && keybindings.matches(KeyAction::SessionForceQuit, key) {
            next_mode = Some(InputMode::Normal);
            cancel_search_reason = Some("force_quit");
            quit_after_filter = Some(true);
            debug_log_key_event(key, "filter_searching_force_quit");
        } else if filter_is_searching {
            debug_log_key_event(key, "filter_searching_ignored");
        } else if keybindings.matches(KeyAction::FilterApply, key) {
            apply_query = Some(draft.clone());
        } else if keybindings.matches(KeyAction::FilterMoveLeft, key) {
            *cursor = prev_char_boundary(draft, *cursor);
            debug_log(
                "filter_cursor",
                serde_json::json!({
                    "action": "left",
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::FilterMoveRight, key) {
            *cursor = next_char_boundary(draft, *cursor);
            debug_log(
                "filter_cursor",
                serde_json::json!({
                    "action": "right",
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::FilterHome, key) {
            *cursor = 0;
            debug_log(
                "filter_cursor",
                serde_json::json!({
                    "action": "home",
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::FilterEnd, key) {
            *cursor = draft.len();
            debug_log(
                "filter_cursor",
                serde_json::json!({
                    "action": "end",
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::FilterBackspace, key) {
            delete_before_cursor(draft, cursor);
            debug_log(
                "filter_backspace",
                serde_json::json!({
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if keybindings.matches(KeyAction::FilterDelete, key) {
            delete_at_cursor(draft, cursor);
            debug_log(
                "filter_delete",
                serde_json::json!({
                    "draft_len": draft.chars().count(),
                    "cursor": *cursor,
                }),
            );
        } else if let KeyCode::Char(c) = key.code {
            if !key.modifiers.contains(KeyModifiers::CONTROL)
                && !key.modifiers.contains(KeyModifiers::ALT)
            {
                insert_at_cursor(draft, cursor, c);
                debug_log(
                    "filter_insert",
                    serde_json::json!({
                        "draft_len": draft.chars().count(),
                        "cursor": *cursor,
                    }),
                );
            } else {
                debug_log_key_event(key, "filter_ignored");
            }
        } else {
            debug_log_key_event(key, "filter_ignored");
        }
        if let Some(reason) = cancel_search_reason {
            app.cancel_pending_search(reason);
        }
        if let Some(mode) = next_mode {
            app.input_mode = mode;
        }
        if let Some(force) = quit_after_filter {
            app.request_quit("filter_searching_quit", force);
            return;
        }
        if let Some(query) = apply_query {
            app.start_text_search(query);
        }
        return;
    }
    // Normal mode
    if let Some(delta) = sessions_pane_resize_key(&keybindings, key) {
        app.adjust_sessions_pane_width(delta, total_width);
        return;
    }
    if let Some(delta) = sessions_sidebar_select_key(&keybindings, key) {
        app.focus = FocusPane::Sessions;
        app.move_selection(delta);
        return;
    }
    if key.code == KeyCode::Esc && key.modifiers.is_empty() {
        if app.clear_session_search_results("esc") {
            debug_log_session_key(app, key, "esc_clear_search");
            return;
        }
        if app.request_quit("esc_quit", false) {
            debug_log_session_key(app, key, "esc_quit");
        } else {
            debug_log_session_key(app, key, "esc_quit_blocked");
        }
        return;
    }
    if keybindings.matches(KeyAction::SessionToggleAgent, key) {
        // Window toggle. If an agent is already active in this process,
        // flip to its view. Otherwise reconnect to a known live daemon
        // without starting a new one.
        debug_log(
            "sessions_toggle_agent_requested",
            serde_json::json!({
                "active_agent": app.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                "show_sessions_view_before": app.show_sessions_view,
                "agent_states_before": agent_state_entries_debug_value(&app.agent_states),
                "live_shells_before": app.live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
                "runtime_refresh_pending": app.runtime_refresh_pending,
                "runtime_refresh_queued": app.runtime_refresh_queued,
                "runtime_refresh_seq": app.runtime_refresh_seq,
                "live_shell_discovery_pending": app.live_shell_discovery_pending,
                "live_shell_discovery_seq": app.live_shell_discovery_seq,
                "pending_runtime_action": pending_runtime_action_debug_value(app.pending_runtime_action.as_ref()),
                "selected": app.current().map(session_info_debug_value),
            }),
        );
        app.toggle_screens(agent_cols.max(1), agent_rows.max(1));
        debug_log(
            "sessions_toggle_agent_done",
            serde_json::json!({
                "active_agent": app.active_agent.as_ref().map(|agent| session_info_debug_value(&agent.info)),
                "show_sessions_view_after": app.show_sessions_view,
                "agent_states_after": agent_state_entries_debug_value(&app.agent_states),
                "live_shells_after": app.live_shells.iter().map(session_info_debug_value).collect::<Vec<_>>(),
                "runtime_refresh_pending": app.runtime_refresh_pending,
                "runtime_refresh_queued": app.runtime_refresh_queued,
                "runtime_refresh_seq": app.runtime_refresh_seq,
                "live_shell_discovery_pending": app.live_shell_discovery_pending,
                "live_shell_discovery_seq": app.live_shell_discovery_seq,
                "pending_runtime_action": pending_runtime_action_debug_value(app.pending_runtime_action.as_ref()),
                "status": &app.status,
            }),
        );
        return;
    }
    if keybindings.matches(KeyAction::SessionKillAgent, key) {
        app.kill_selected_agent();
        return;
    }
    if keybindings.matches(KeyAction::SessionQuit, key) {
        if app.request_quit("quit", false) {
            debug_log_session_key(app, key, "quit");
        } else {
            debug_log_session_key(app, key, "quit_blocked");
        }
    } else if keybindings.matches(KeyAction::SessionForceQuit, key) {
        if app.request_quit("ctrl_c_quit", true) {
            debug_log_session_key(app, key, "ctrl_c_quit");
        } else {
            debug_log_session_key(app, key, "ctrl_c_quit_blocked");
        }
    } else if keybindings.matches(KeyAction::SessionNewShell, key) {
        app.begin_new_session_from_focused();
    } else if keybindings.matches(KeyAction::SessionToggleFocus, key) {
        app.toggle_focus();
    } else if keybindings.matches(KeyAction::SessionLaunchAgent, key) {
        app.begin_agent_launch(agent_cols.max(1), agent_rows.max(1));
    } else if keybindings.matches(KeyAction::SessionTogglePreview, key) {
        app.show_summary_preview();
    } else if keybindings.matches(KeyAction::SessionMoveNext, key) {
        if app.focus == FocusPane::Preview {
            app.scroll_preview(1);
        } else {
            app.move_selection(1);
        }
    } else if keybindings.matches(KeyAction::SessionMovePrev, key) {
        if app.focus == FocusPane::Preview {
            app.scroll_preview(-1);
        } else {
            app.move_selection(-1);
        }
    } else if keybindings.matches(KeyAction::SessionPageNext, key) {
        if app.focus == FocusPane::Preview {
            app.scroll_preview_page(1);
        } else {
            app.move_selection(10);
        }
    } else if keybindings.matches(KeyAction::SessionPagePrev, key) {
        if app.focus == FocusPane::Preview {
            app.scroll_preview_page(-1);
        } else {
            app.move_selection(-10);
        }
    } else if keybindings.matches(KeyAction::SessionTop, key) {
        if app.focus == FocusPane::Preview {
            app.preview_top();
        } else {
            app.select_first();
        }
    } else if keybindings.matches(KeyAction::SessionBottom, key) {
        if app.focus == FocusPane::Preview {
            app.preview_bottom();
        } else {
            app.select_last();
        }
    } else if keybindings.matches(KeyAction::SessionFilter, key) {
        app.begin_search_choice();
    } else if keybindings.matches(KeyAction::SessionAiSearch, key) {
        app.begin_ai_search();
    } else if keybindings.matches(KeyAction::SessionToggleView, key) {
        app.toggle_session_view();
    } else if keybindings.matches(KeyAction::SessionRefresh, key) {
        app.request_session_refresh();
    } else if keybindings.matches(KeyAction::SessionDelete, key) {
        if app.reject_while_data_task_running("deleting a session") {
            return;
        }
        if let Some(info) = app.current().cloned() {
            let removed_index = app.list_state.selected();
            debug_log(
                "delete_confirm_open",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                }),
            );
            app.input_mode = InputMode::DeleteConfirm {
                info,
                removed_index,
                selected: DELETE_OPTION_CANCEL,
            };
        }
    } else if keybindings.matches(KeyAction::SessionClone, key) {
        if app.reject_while_data_task_running("cloning a session") {
            return;
        }
        if let Some(info) = app.current().cloned() {
            debug_log(
                "clone_prompt_open",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": &info.session_id,
                }),
            );
            let target = info.provider;
            app.begin_clone_session(info, target);
        }
    } else if keybindings.matches(KeyAction::SessionAiTitleSettings, key)
        && app.focus == FocusPane::Sessions
    {
        app.begin_settings(AiTitleSettingsReturn::Normal);
    } else if keybindings.matches(KeyAction::SessionEditTitle, key)
        && app.focus == FocusPane::Sessions
    {
        app.begin_title_edit();
    } else if keybindings.matches(KeyAction::SessionRefreshPreview, key) {
        // Force a re-render of the preview (and refresh cache).
        if let Some(info) = app.current().cloned() {
            let key = PreviewKey::new(&info, app.preview_mode);
            app.drop_cached_preview(&key);
            app.preview_requested = None;
            debug_log(
                "preview_force_refresh",
                serde_json::json!({
                    "provider": info.provider.as_str(),
                    "session_id": info.session_id,
                    "mode": preview_mode_label(app.preview_mode),
                }),
            );
        } else {
            app.clear_preview_cache();
            debug_log("preview_force_refresh_all", serde_json::json!({}));
        }
    } else {
        debug_log_session_key(app, key, "normal_ignored");
    }
}

fn ui(f: &mut ratatui::Frame, app: &mut App) {
    let area = f.area();
    let outer = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(1), Constraint::Length(2)])
        .split(area);

    let sessions_width = app.sessions_pane_width(outer[0].width);
    let preview_width = outer[0].width.saturating_sub(sessions_width);
    let main = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Length(sessions_width),
            Constraint::Length(preview_width),
        ])
        .split(outer[0]);

    f.render_widget(Clear, main[0]);
    draw_list(f, app, main[0]);
    f.render_widget(Clear, main[1]);
    draw_preview(f, app, main[1]);
    f.render_widget(Clear, outer[1]);
    draw_status(f, app, outer[1]);

    draw_input_modal(f, area, app);
    draw_ai_search_pending_overlay(f, area, app.ai_search_pending.as_ref());
}

fn draw_delete_confirm_modal(
    f: &mut ratatui::Frame,
    area: Rect,
    info: &SessionInfo,
    selected: usize,
    keybindings: &KeyBindings,
) {
    let lines = delete_confirm_lines(info, selected, keybindings);
    let modal_area = modal_area_for_wrapped_lines(area, "Delete session", &lines, 48, 86, 7, 12);
    fill_area(f.buffer_mut(), modal_area, theme_alt_style());
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(THEME_BORDER_ACTIVE))
        .style(theme_alt_style())
        .title("Delete session");
    let p = Paragraph::new(lines)
        .block(block)
        .style(theme_alt_style())
        .wrap(Wrap { trim: false });
    f.render_widget(ratatui::widgets::Clear, modal_area);
    f.render_widget(p, modal_area);
}

fn delete_confirm_lines(
    info: &SessionInfo,
    selected: usize,
    keybindings: &KeyBindings,
) -> Vec<Line<'static>> {
    vec![
        Line::from(Span::styled(
            format!("Delete {} session?", info.provider.as_str()),
            Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT),
        )),
        Line::from(Span::styled(
            format!("Session: {}", confirm_prompt_line(&info.session_id, 64)),
            Style::default().fg(THEME_ACCENT).bg(THEME_BG_ALT),
        )),
        Line::from(Span::styled(
            "This removes stored history.",
            Style::default().fg(THEME_FG_DIM).bg(THEME_BG_ALT),
        )),
        Line::from(""),
        delete_confirm_button_line(selected),
        modal_help_line(&delete_confirm_help_items(keybindings)),
    ]
}

fn delete_confirm_button_line(selected: usize) -> Line<'static> {
    Line::from(vec![
        delete_confirm_button_span("1 Delete session", selected == DELETE_OPTION_DELETE),
        Span::raw("  "),
        delete_confirm_button_span("2 Cancel", selected == DELETE_OPTION_CANCEL),
    ])
}

fn delete_confirm_button_span(label: &str, selected: bool) -> Span<'static> {
    let text = format!("{}{}", selection_marker(selected), label);
    let style = if selected {
        theme_selected_style()
    } else {
        Style::default().fg(THEME_FG_STRONG).bg(THEME_BG_ALT)
    };
    Span::styled(text, style)
}

