    #[test]
    fn ai_title_transcript_uses_summary_for_large_sessions() {
        let mut session =
            UniversalSession::new("large-ai-title", Provider::Codex, "/shared/cokacmux");
        session.messages.push(test_message(
            0,
            cokacmux::Role::User,
            &"x".repeat(AI_TITLE_FULL_TRANSCRIPT_MAX_CHARS + 1_000),
        ));

        let transcript = ai_title_transcript_for_prompt(&session);

        assert_eq!(transcript.mode, "summary");
        assert!(transcript.full_chars > AI_TITLE_FULL_TRANSCRIPT_MAX_CHARS);
        assert!(transcript.text.contains("Large session note"));
        assert!(transcript.text.contains("USER #0"));
        assert!(
            transcript.text.chars().count() < AI_TITLE_FULL_TRANSCRIPT_MAX_CHARS / 4,
            "summary transcript should be much smaller than the full rendered session"
        );
    }

    #[test]
    fn ai_title_process_error_reports_tail_instead_of_codex_banner() {
        let output = AiTitleCommandOutput {
            status: None,
            stdout: "context length exceeded\ntry a shorter prompt\n".to_string(),
            stderr: format!(
                "OpenAI Codex v0.0.0\n--------\nworkdir: /shared/cokacmux\nmodel: gpt-5.5\nprovider: openai\nuser\n{}\nerror: request too large\n",
                "prompt ".repeat(200)
            ),
            cancelled: false,
            timed_out: false,
            duration: Duration::from_secs(1),
        };

        let error = ai_title_process_error("codex", &output);

        assert!(error.contains("context length exceeded"));
        assert!(error.contains("error: request too large"));
        assert!(!error.contains("OpenAI Codex v0.0.0"));
        assert!(!error.contains("workdir: /shared/cokacmux"));
    }

    #[cfg(unix)]
    #[test]
    fn prompt_command_timeout_does_not_block_on_large_stdin_write() {
        let shell = Path::new("/bin/sh");
        if !shell.is_file() {
            return;
        }
        let mut command = Command::new(shell);
        command.args(["-c", "trap '' TERM; while :; do sleep 1; done"]);
        let started = Instant::now();

        let output =
            run_prompt_command(command, &"x".repeat(2_000_000), Duration::from_millis(200))
                .unwrap();

        assert!(output.timed_out);
        assert!(!output.cancelled);
        assert!(
            started.elapsed() < Duration::from_secs(3),
            "timeout was delayed by a blocking stdin write"
        );
    }

    #[cfg(unix)]
    #[test]
    fn prompt_command_cancel_does_not_block_on_large_stdin_write() {
        let shell = Path::new("/bin/sh");
        if !shell.is_file() {
            return;
        }
        let cancel = Arc::new(AtomicBool::new(false));
        let cancel_thread = {
            let cancel = cancel.clone();
            thread::spawn(move || {
                thread::sleep(Duration::from_millis(150));
                cancel.store(true, Ordering::Relaxed);
            })
        };
        let mut command = Command::new(shell);
        command.args(["-c", "trap '' TERM; while :; do sleep 1; done"]);
        let started = Instant::now();

        let output = run_prompt_command_with_cancel(
            command,
            &"x".repeat(2_000_000),
            Duration::from_secs(30),
            Some(&cancel),
        )
        .unwrap();
        let _ = cancel_thread.join();

        assert!(output.cancelled);
        assert!(!output.timed_out);
        assert!(
            started.elapsed() < Duration::from_secs(3),
            "cancel was delayed by a blocking stdin write"
        );
    }

    #[cfg(unix)]
    #[test]
    fn prompt_command_timeout_kills_descendant_holding_output_pipe() {
        let shell = Path::new("/bin/sh");
        if !shell.is_file() {
            return;
        }
        let mut command = Command::new(shell);
        command.args(["-c", "(trap '' TERM; while :; do sleep 1; done) & wait"]);
        let started = Instant::now();

        let output = run_prompt_command(command, "", Duration::from_millis(200)).unwrap();

        assert!(output.timed_out);
        assert!(
            started.elapsed() < Duration::from_secs(3),
            "timeout was delayed by a descendant holding stdout/stderr open"
        );
    }

    #[cfg(unix)]
    #[test]
    fn prompt_command_completed_child_kills_descendant_holding_output_pipe() {
        let shell = Path::new("/bin/sh");
        if !shell.is_file() {
            return;
        }
        let mut command = Command::new(shell);
        command.args(["-c", "(trap '' TERM; while :; do sleep 1; done) & exit 0"]);
        let started = Instant::now();

        let output = run_prompt_command(command, "", Duration::from_secs(30)).unwrap();

        assert!(!output.timed_out);
        assert!(
            output.status.is_some_and(|status| status.success()),
            "expected shell to exit successfully"
        );
        assert!(
            started.elapsed() < Duration::from_secs(3),
            "completion was delayed by a descendant holding stdout/stderr open"
        );
    }

