    #[test]
    fn cokacmux_dark_theme_colors_are_indexed() {
        let colors = [
            THEME_BG,
            THEME_BG_ALT,
            THEME_STATUS_BG,
            THEME_FG,
            THEME_FG_DIM,
            THEME_FG_STRONG,
            THEME_SELECTED_BG,
            THEME_SELECTED_TEXT,
            THEME_ACCENT,
            THEME_SHORTCUT,
            THEME_POSITIVE,
            THEME_WARNING,
            THEME_ERROR,
            THEME_BORDER,
            THEME_BORDER_ACTIVE,
            THEME_PROVIDER_CLAUDE,
            THEME_PROVIDER_CODEX,
            THEME_PROVIDER_OPENCODE,
            THEME_PREVIEW_USER,
            THEME_PREVIEW_ASSISTANT,
            THEME_PREVIEW_TOOL,
            THEME_PREVIEW_THINKING,
            THEME_PREVIEW_ERROR,
            THEME_PREVIEW_IMAGE,
            THEME_PREVIEW_PATCH_REMOVE,
            THEME_PREVIEW_SYSTEM,
            THEME_PREVIEW_DEVELOPER,
            THEME_PREVIEW_FIELD,
            THEME_PREVIEW_KEY,
            THEME_PREVIEW_ID,
            THEME_PREVIEW_PATH,
            THEME_PREVIEW_TIME,
            THEME_PREVIEW_ATTACHMENT,
            THEME_PREVIEW_OTHER,
            THEME_PREVIEW_PATCH_HEADER,
            AGENT_DEFAULT_BG,
        ];
        assert!(colors
            .iter()
            .all(|color| matches!(color, Color::Indexed(_))));
        assert_eq!(THEME_BG, Color::Indexed(234));
        assert_eq!(THEME_SELECTED_BG, Color::Indexed(66));
        assert_eq!(THEME_POSITIVE, Color::Indexed(108));
        assert_eq!(THEME_WARNING, Color::Indexed(214));
        assert_eq!(THEME_ERROR, Color::Indexed(203));
        assert_eq!(THEME_ACCENT, Color::Indexed(109));
    }

