    #[test]
    fn clone_data_task_locks_input_except_esc_cancel() {
        let cancel_token = Arc::new(AtomicBool::new(false));
        let mut app = app_for_key_tests();
        app.sessions
            .push(session_info(Provider::Codex, "first", "/repo/one"));
        app.sessions
            .push(session_info(Provider::Codex, "second", "/repo/two"));
        app.list_state.select(Some(0));
        app.data_task = Some(
            DataTaskPending::new(
                1,
                DataTaskKind::Clone,
                "cloning codex session + folder data".to_string(),
            )
            .with_cancel_token(cancel_token.clone()),
        );

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Char('j'), KeyModifiers::NONE),
            100,
            80,
            20,
        );

        assert_eq!(app.list_state.selected(), Some(0));
        assert!(!cancel_token.load(Ordering::Relaxed));
        assert!(app.status.contains("press Esc to cancel"));

        handle_key(
            &mut app,
            KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE),
            100,
            80,
            20,
        );

        assert!(cancel_token.load(Ordering::Relaxed));
        let task = app.data_task.as_ref().expect("clone task remains pending");
        assert!(task.cancel_requested);
        assert!(app.status.contains("cancellation requested"));
    }

    #[test]
    fn session_mutating_actions_are_blocked_while_data_task_runs() {
        let dir = tempfile::tempdir().unwrap();
        let mut app = app_for_key_tests();
        app.sessions.push(session_info(
            Provider::Codex,
            "blocked-session",
            &dir.path().display().to_string(),
        ));
        app.list_state.select(Some(0));

        for key in [
            KeyEvent::new(KeyCode::Char('e'), KeyModifiers::NONE),
            KeyEvent::new(KeyCode::Char('c'), KeyModifiers::NONE),
            KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE),
            KeyEvent::new(KeyCode::Char('n'), KeyModifiers::CONTROL),
        ] {
            app.input_mode = InputMode::Normal;
            app.status.clear();
            app.data_task = Some(DataTaskPending::new(
                1,
                DataTaskKind::Restore,
                "restoring folder data".to_string(),
            ));

            handle_key(&mut app, key, 100, 80, 20);

            assert!(matches!(app.input_mode, InputMode::Normal));
            assert!(app.status.contains("restore in progress"));
            assert!(app.data_task.is_some());
        }
    }

    #[cfg(windows)]
    #[test]
    fn windows_agent_tcp_marker_accepts_loopback_addr_only() {
        let marker_path = std::env::temp_dir().join(format!(
            "cokacmux-agent-marker-test-{}.tcp",
            std::process::id()
        ));
        fs::write(&marker_path, "tcp 127.0.0.1:49321\n").unwrap();
        assert_eq!(
            read_agent_tcp_addr(&marker_path).unwrap(),
            "127.0.0.1:49321"
        );

        fs::write(&marker_path, "tcp 0.0.0.0:49321\n").unwrap();
        assert_eq!(
            read_agent_tcp_addr(&marker_path).unwrap_err().kind(),
            ErrorKind::InvalidData
        );
        let _ = fs::remove_file(marker_path);
    }

