    #[test]
    fn discovery_strike_prune_survives_stale_resurrection() {
        let mut app = app_for_key_tests();
        let ghost = session_info(Provider::Claude, "ghost-shell", "/repo");
        let ghost_key = AgentKey::new(&ghost);
        let quiet = AgentListState::Live {
            activity: AgentActivity::Quiet,
        };
        app.live_shells = vec![ghost.clone()];
        app.agent_states.insert(ghost_key.clone(), quiet);

        let empty_scan = |seq: u64| LiveShellDiscoveryResult {
            seq,
            live_shells: Vec::new(),
            started_at_epoch_ms: current_epoch_ms(),
            queued_at_epoch_ms: current_epoch_ms(),
            elapsed_ms: 1,
        };

        // Misses within the limit preserve the shell.
        for seq in 1..=u64::from(LIVE_SHELL_DISCOVERY_PRESERVE_MISS_LIMIT) {
            app.live_shell_discovery_seq = seq;
            app.live_shell_discovery_pending = true;
            app.on_live_shell_discovery_result(empty_scan(seq));
            assert_eq!(app.live_shells.len(), 1, "miss {} must preserve", seq);
        }

        // The next consecutive miss prunes it and cleans its state.
        let prune_seq = u64::from(LIVE_SHELL_DISCOVERY_PRESERVE_MISS_LIMIT) + 1;
        app.live_shell_discovery_seq = prune_seq;
        app.live_shell_discovery_pending = true;
        app.on_live_shell_discovery_result(empty_scan(prune_seq));
        assert!(
            app.live_shells.is_empty(),
            "ghost survived the strike limit"
        );
        assert!(!app.agent_states.contains_key(&ghost_key));

        // A stale in-flight runtime result can resurrect the ghost; the
        // parked strike counter must prune it again on the very next scan
        // instead of granting a fresh round of preservation.
        app.live_shells = vec![ghost.clone()];
        app.agent_states.insert(ghost_key.clone(), quiet);
        let again_seq = prune_seq + 1;
        app.live_shell_discovery_seq = again_seq;
        app.live_shell_discovery_pending = true;
        app.on_live_shell_discovery_result(empty_scan(again_seq));
        assert!(
            app.live_shells.is_empty(),
            "resurrected ghost must be pruned immediately"
        );
        assert!(!app.agent_states.contains_key(&ghost_key));
    }

    fn large_output_with_tail_marker() -> Vec<u8> {
        let mut out = Vec::new();
        for line in 0..10_000 {
            out.extend_from_slice(format!("BUFFERED-LINE-{line:05}\r\n").as_bytes());
        }
        out.extend_from_slice(b"COKACMUX_TAIL_MARKER\r\n");
        out
    }

    fn active_agent_visible_text(app: &mut App) -> String {
        let agent = app.active_agent.as_mut().unwrap();
        parser_visible_plain_lines(&mut agent.parser, 0).join("\n")
    }

    fn active_agent_has_pending_output(app: &App) -> bool {
        app.active_agent
            .as_ref()
            .is_some_and(AgentClient::has_pending_output)
    }

    fn drain_active_agent_output_until_idle(app: &mut App, reader_id: u64) {
        for _ in 0..100 {
            if !active_agent_has_pending_output(app) {
                return;
            }
            app.on_agent_output_available(reader_id);
        }
        panic!("active agent output did not drain within the iteration limit");
    }

    #[cfg(unix)]
    #[test]
    fn terminal_event_defers_large_pending_output_and_preserves_tail() {
        let reader_id = 19;
        let mut app = app_for_key_tests();
        app.active_agent = Some(buffered_output_test_client("large-output-exit", reader_id));

        let (tx, _rx) = mpsc::channel::<MainEvent>();
        let output_buffer = app.active_agent.as_ref().unwrap().output_buffer.clone();
        queue_agent_output(
            &output_buffer,
            &tx,
            reader_id,
            AgentOutputKind::Output,
            large_output_with_tail_marker(),
        )
        .unwrap();

        app.on_agent_output_available(reader_id);
        assert!(!active_agent_visible_text(&mut app).contains("COKACMUX_TAIL_MARKER"));

        app.on_agent_event(
            reader_id,
            AgentDaemonEvent::Exited {
                status: "done".into(),
            },
        );

        assert_eq!(
            app.active_agent.as_ref().unwrap().exited.as_deref(),
            Some("done")
        );
        assert!(active_agent_has_pending_output(&app));
        assert!(!active_agent_visible_text(&mut app).contains("COKACMUX_TAIL_MARKER"));

        drain_active_agent_output_until_idle(&mut app, reader_id);
        let text = active_agent_visible_text(&mut app);
        assert!(
            text.contains("COKACMUX_TAIL_MARKER"),
            "terminal output tail should survive incremental exit draining: {:?}",
            text
        );
        app.poll_agent_sessions();
        assert!(app.active_agent.is_none());
    }

