    #[cfg(unix)]
    #[test]
    fn terminate_agent_child_process_kills_separate_process_group() {
        let shell = Path::new("/bin/sh");
        if !shell.is_file() {
            return;
        }

        let mut command = Command::new(shell);
        command
            .args(["-c", "trap '' HUP TERM; while :; do sleep 1; done"])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        unsafe {
            command.pre_exec(|| {
                if libc::setsid() == -1 {
                    Err(io::Error::last_os_error())
                } else {
                    Ok(())
                }
            });
        }
        let mut child = command.spawn().unwrap();
        let child_pid = child.id();
        let info = session_info(Provider::Claude, "kill-child", "/repo");
        let key = AgentKey::new(&info);

        assert_eq!(
            terminate_agent_child_process(Some(child_pid), 1, &key),
            Some(child_pid)
        );

        assert_process_exits(&mut child, "PTY child process group survived termination");
    }

    #[cfg(unix)]
    #[test]
    fn terminate_process_group_falls_back_to_direct_pid_kill() {
        let mut child = match Command::new("sleep")
            .arg("30")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
        {
            Ok(child) => child,
            Err(_) => return,
        };
        let child_pid = child.id();

        terminate_process_group(child_pid);

        let start = Instant::now();
        let mut exited = false;
        while start.elapsed() < Duration::from_secs(2) {
            if child.try_wait().unwrap().is_some() {
                exited = true;
                break;
            }
            thread::sleep(Duration::from_millis(20));
        }
        if !exited {
            let _ = child.kill();
        }
        let _ = child.wait();
        assert!(
            exited,
            "direct-pid fallback failed to terminate a non-group-leader process"
        );
    }

    #[test]
    fn killall_removes_stale_agent_runtime_files() {
        let dir = tempfile::tempdir().unwrap();
        let scrollback = dir.path().join("scrollback");
        fs::create_dir_all(&scrollback).unwrap();
        let stem = "codex-stale";
        let info = session_info(Provider::Codex, "stale", "/tmp/killall-stale-lock");
        let cwd_lock = dir.path().join("cwd-stale.lock");
        fs::write(
            dir.path().join(format!("{}.json", stem)),
            r#"{"pid":3000000000,"provider":"codex","session_id":"stale"}"#,
        )
        .unwrap();
        fs::write(dir.path().join(format!("{}.sock", stem)), "").unwrap();
        fs::write(scrollback.join(format!("{}.ptylog", stem)), b"OLD\n").unwrap();
        fs::write(
            &cwd_lock,
            serde_json::to_string_pretty(&coding_agent_cwd_lock_for_info(
                &info,
                0,
                CODING_AGENT_CWD_LOCK_OWNER_AGENT,
            ))
            .unwrap(),
        )
        .unwrap();

        let report = kill_all_agent_daemons_at(dir.path(), std::process::id());

        assert_eq!(report.scanned, 1);
        assert_eq!(report.stale, 1);
        assert_eq!(report.killed, 0);
        assert_eq!(report.pty_logs_deleted, 1);
        assert_eq!(report.cwd_locks_removed, 1);
        assert!(!dir.path().join(format!("{}.json", stem)).exists());
        assert!(!dir.path().join(format!("{}.sock", stem)).exists());
        assert!(!scrollback.join(format!("{}.ptylog", stem)).exists());
        assert!(!cwd_lock.exists());
    }

    #[cfg(unix)]
    #[test]
    fn killall_terminates_child_from_stale_daemon_meta() {
        let mut child = match Command::new("sleep")
            .arg("30")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
        {
            Ok(child) => child,
            Err(_) => return,
        };
        let child_pid = child.id();
        let dir = tempfile::tempdir().unwrap();
        let info = session_info(Provider::Codex, "stale-child", "/tmp/stale-child");
        let key = AgentKey::new(&info);
        let stem = agent_file_stem(&key);
        fs::write(
            dir.path().join(format!("{stem}.json")),
            serde_json::json!({
                "pid": 3000000000u32,
                "child_pid": child_pid,
                "child_pid_start_ticks": process_start_ticks(child_pid),
                "provider": info.provider.as_str(),
                "session_id": &info.session_id,
                "cwd": &info.cwd,
                "source": info.source.display().to_string(),
                "updated_at_epoch_s": current_epoch_s(),
            })
            .to_string(),
        )
        .unwrap();

        let report = kill_all_agent_daemons_at(dir.path(), std::process::id());

        assert_eq!(report.stale, 1);
        assert_eq!(report.child_processes_terminated, 1);
        assert_process_exits(&mut child, "stale daemon child survived killall");
    }

